1639|static size_t
1640|ZSTD_sizeof_matchState(const ZSTD_compressionParameters* const cParams,
1641|                       const ZSTD_paramSwitch_e useRowMatchFinder,
1642|                       const U32 enableDedicatedDictSearch,
1643|                       const U32 forCCtx)
1644|{
1645|    /* chain table size should be 0 for fast or row-hash strategies */
1646|    size_t const chainSize = ZSTD_allocateChainTable(cParams->strategy, useRowMatchFinder, enableDedicatedDictSearch && !forCCtx)
1647|                                ? ((size_t)1 << cParams->chainLog)
1648|                                : 0;
1649|    size_t const hSize = ((size_t)1) << cParams->hashLog;
1650|    U32    const hashLog3 = (forCCtx && cParams->minMatch==3) ? MIN(ZSTD_HASHLOG3_MAX, cParams->windowLog) : 0;
1651|    size_t const h3Size = hashLog3 ? ((size_t)1) << hashLog3 : 0;
1652|    /* We don't use ZSTD_cwksp_alloc_size() here because the tables aren't
1653|     * surrounded by redzones in ASAN. */
1654|    size_t const tableSpace = chainSize * sizeof(U32)
1655|                            + hSize * sizeof(U32)
1656|                            + h3Size * sizeof(U32);
1657|    size_t const optPotentialSpace =
1658|        ZSTD_cwksp_aligned_alloc_size((MaxML+1) * sizeof(U32))
1659|      + ZSTD_cwksp_aligned_alloc_size((MaxLL+1) * sizeof(U32))
1660|      + ZSTD_cwksp_aligned_alloc_size((MaxOff+1) * sizeof(U32))
1661|      + ZSTD_cwksp_aligned_alloc_size((1<<Litbits) * sizeof(U32))
1662|      + ZSTD_cwksp_aligned_alloc_size((ZSTD_OPT_NUM+1) * sizeof(ZSTD_match_t))
1663|      + ZSTD_cwksp_aligned_alloc_size((ZSTD_OPT_NUM+1) * sizeof(ZSTD_optimal_t));
1664|    size_t const lazyAdditionalSpace = ZSTD_rowMatchFinderUsed(cParams->strategy, useRowMatchFinder)
1665|                                            ? ZSTD_cwksp_aligned_alloc_size(hSize)
1666|                                            : 0;
1667|    size_t const optSpace = (forCCtx && (cParams->strategy >= ZSTD_btopt))
1668|                                ? optPotentialSpace
1669|                                : 0;
1670|    size_t const slackSpace = ZSTD_cwksp_slack_space_required();
1671|
1672|    /* tables are guaranteed to be sized in multiples of 64 bytes (or 16 uint32_t) */
1673|    ZSTD_STATIC_ASSERT(ZSTD_HASHLOG_MIN >= 4 && ZSTD_WINDOWLOG_MIN >= 4 && ZSTD_CHAINLOG_MIN >= 4);
1674|    assert(useRowMatchFinder != ZSTD_ps_auto);
1675|
1676|    DEBUGLOG(4, "chainSize: %u - hSize: %u - h3Size: %u",
1677|                (U32)chainSize, (U32)hSize, (U32)h3Size);
1678|    return tableSpace + optSpace + slackSpace + lazyAdditionalSpace;
1679|}
