1681|/* Helper function for calculating memory requirements.
1682| * Gives a tighter bound than ZSTD_sequenceBound() by taking minMatch into account. */
1683|static size_t ZSTD_maxNbSeq(size_t blockSize, unsigned minMatch, int useSequenceProducer) {
1684|    U32 const divider = (minMatch==3 || useSequenceProducer) ? 3 : 4;
1685|    return blockSize / divider;
1686|}
