1688|static size_t ZSTD_estimateCCtxSize_usingCCtxParams_internal(
1689|        const ZSTD_compressionParameters* cParams,
1690|        const ldmParams_t* ldmParams,
1691|        const int isStatic,
1692|        const ZSTD_paramSwitch_e useRowMatchFinder,
1693|        const size_t buffInSize,
1694|        const size_t buffOutSize,
1695|        const U64 pledgedSrcSize,
1696|        int useSequenceProducer,
1697|        size_t maxBlockSize)
1698|{
1699|    size_t const windowSize = (size_t) BOUNDED(1ULL, 1ULL << cParams->windowLog, pledgedSrcSize);
1700|    size_t const blockSize = MIN(ZSTD_resolveMaxBlockSize(maxBlockSize), windowSize);
1701|    size_t const maxNbSeq = ZSTD_maxNbSeq(blockSize, cParams->minMatch, useSequenceProducer);
1702|    size_t const tokenSpace = ZSTD_cwksp_alloc_size(WILDCOPY_OVERLENGTH + blockSize)
1703|                            + ZSTD_cwksp_aligned_alloc_size(maxNbSeq * sizeof(seqDef))
1704|                            + 3 * ZSTD_cwksp_alloc_size(maxNbSeq * sizeof(BYTE));
1705|    size_t const entropySpace = ZSTD_cwksp_alloc_size(ENTROPY_WORKSPACE_SIZE);
1706|    size_t const blockStateSpace = 2 * ZSTD_cwksp_alloc_size(sizeof(ZSTD_compressedBlockState_t));
1707|    size_t const matchStateSize = ZSTD_sizeof_matchState(cParams, useRowMatchFinder, /* enableDedicatedDictSearch */ 0, /* forCCtx */ 1);
1708|
1709|    size_t const ldmSpace = ZSTD_ldm_getTableSize(*ldmParams);
1710|    size_t const maxNbLdmSeq = ZSTD_ldm_getMaxNbSeq(*ldmParams, blockSize);
1711|    size_t const ldmSeqSpace = ldmParams->enableLdm == ZSTD_ps_enable ?
1712|        ZSTD_cwksp_aligned_alloc_size(maxNbLdmSeq * sizeof(rawSeq)) : 0;
1713|
1714|
1715|    size_t const bufferSpace = ZSTD_cwksp_alloc_size(buffInSize)
1716|                             + ZSTD_cwksp_alloc_size(buffOutSize);
1717|
1718|    size_t const cctxSpace = isStatic ? ZSTD_cwksp_alloc_size(sizeof(ZSTD_CCtx)) : 0;
1719|
1720|    size_t const maxNbExternalSeq = ZSTD_sequenceBound(blockSize);
1721|    size_t const externalSeqSpace = useSequenceProducer
1722|        ? ZSTD_cwksp_aligned_alloc_size(maxNbExternalSeq * sizeof(ZSTD_Sequence))
1723|        : 0;
1724|
1725|    size_t const neededSpace =
1726|        cctxSpace +
1727|        entropySpace +
1728|        blockStateSpace +
1729|        ldmSpace +
1730|        ldmSeqSpace +
1731|        matchStateSize +
1732|        tokenSpace +
1733|        bufferSpace +
1734|        externalSeqSpace;
1735|
1736|    DEBUGLOG(5, "estimate workspace : %u", (U32)neededSpace);
1737|    return neededSpace;
1738|}
