1755|size_t ZSTD_estimateCCtxSize_usingCParams(ZSTD_compressionParameters cParams)
1756|{
1757|    ZSTD_CCtx_params initialParams = ZSTD_makeCCtxParamsFromCParams(cParams);
1758|    if (ZSTD_rowMatchFinderSupported(cParams.strategy)) {
1759|        /* Pick bigger of not using and using row-based matchfinder for greedy and lazy strategies */
1760|        size_t noRowCCtxSize;
1761|        size_t rowCCtxSize;
1762|        initialParams.useRowMatchFinder = ZSTD_ps_disable;
1763|        noRowCCtxSize = ZSTD_estimateCCtxSize_usingCCtxParams(&initialParams);
1764|        initialParams.useRowMatchFinder = ZSTD_ps_enable;
1765|        rowCCtxSize = ZSTD_estimateCCtxSize_usingCCtxParams(&initialParams);
1766|        return MAX(noRowCCtxSize, rowCCtxSize);
1767|    } else {
1768|        return ZSTD_estimateCCtxSize_usingCCtxParams(&initialParams);
1769|    }
