1772|static size_t ZSTD_estimateCCtxSize_internal(int compressionLevel)
1773|{
1774|    int tier = 0;
1775|    size_t largestSize = 0;
1776|    static const unsigned long long srcSizeTiers[4] = {16 KB, 128 KB, 256 KB, ZSTD_CONTENTSIZE_UNKNOWN};
1777|    for (; tier < 4; ++tier) {
1778|        /* Choose the set of cParams for a given level across all srcSizes that give the largest cctxSize */
1779|        ZSTD_compressionParameters const cParams = ZSTD_getCParams_internal(compressionLevel, srcSizeTiers[tier], 0, ZSTD_cpm_noAttachDict);
1780|        largestSize = MAX(ZSTD_estimateCCtxSize_usingCParams(cParams), largestSize);
1781|    }
1782|    return largestSize;
1783|}
