1785|size_t ZSTD_estimateCCtxSize(int compressionLevel)
1786|{
1787|    int level;
1788|    size_t memBudget = 0;
1789|    for (level=MIN(compressionLevel, 1); level<=compressionLevel; level++) {
1790|        /* Ensure monotonically increasing memory usage as compression level increases */
1791|        size_t const newMB = ZSTD_estimateCCtxSize_internal(level);
1792|        if (newMB > memBudget) memBudget = newMB;
1793|    }
1794|    return memBudget;
