1851|/* ZSTD_getFrameProgression():
1852| * tells how much data has been consumed (input) and produced (output) for current frame.
1853| * able to count progression inside worker threads (non-blocking mode).
1854| */
1855|ZSTD_frameProgression ZSTD_getFrameProgression(const ZSTD_CCtx* cctx)
1856|{
1857|#ifdef ZSTD_MULTITHREAD
1858|    if (cctx->appliedParams.nbWorkers > 0) {
1859|        return ZSTDMT_getFrameProgression(cctx->mtctx);
1860|    }
1861|#endif
1862|    {   ZSTD_frameProgression fp;
1863|        size_t const buffered = (cctx->inBuff == NULL) ? 0 :
1864|                                cctx->inBuffPos - cctx->inToCompress;
1865|        if (buffered) assert(cctx->inBuffPos >= cctx->inToCompress);
1866|        assert(buffered <= ZSTD_BLOCKSIZE_MAX);
1867|        fp.ingested = cctx->consumedSrcSize + buffered;
1868|        fp.consumed = cctx->consumedSrcSize;
1869|        fp.produced = cctx->producedCSize;
1870|        fp.flushed  = cctx->producedCSize;   /* simplified; some data might still be left within streaming output buffer */
1871|        fp.currentJobID = 0;
1872|        fp.nbActiveWorkers = 0;
1873|        return fp;
1874|}   }
