1929|/**
1930| * Controls, for this matchState reset, whether the tables need to be cleared /
1931| * prepared for the coming compression (ZSTDcrp_makeClean), or whether the
1932| * tables can be left unclean (ZSTDcrp_leaveDirty), because we know that a
1933| * subsequent operation will overwrite the table space anyways (e.g., copying
1934| * the matchState contents in from a CDict).
1935| */
1936|typedef enum {
1937|    ZSTDcrp_makeClean,
1938|    ZSTDcrp_leaveDirty
1939|} ZSTD_compResetPolicy_e;
