1956|/* Mixes bits in a 64 bits in a value, based on XXH3_rrmxmx */
1957|static U64 ZSTD_bitmix(U64 val, U64 len) {
1958|    val ^= ZSTD_rotateRight_U64(val, 49) ^ ZSTD_rotateRight_U64(val, 24);
1959|    val *= 0x9FB21C651E98DF25ULL;
1960|    val ^= (val >> 35) + len ;
1961|    val *= 0x9FB21C651E98DF25ULL;
1962|    return val ^ (val >> 28);
1963|}
