1965|/* Mixes in the hashSalt and hashSaltEntropy to create a new hashSalt */
1966|static void ZSTD_advanceHashSalt(ZSTD_matchState_t* ms) {
1967|    ms->hashSalt = ZSTD_bitmix(ms->hashSalt, 8) ^ ZSTD_bitmix((U64) ms->hashSaltEntropy, 4);
