1981|                                                     ms->dedicatedDictSearch && (forWho == ZSTD_resetTarget_CDict))
1982|                                ? ((size_t)1 << cParams->chainLog)
1983|                                : 0;
1984|    size_t const hSize = ((size_t)1) << cParams->hashLog;
1985|    U32    const hashLog3 = ((forWho == ZSTD_resetTarget_CCtx) && cParams->minMatch==3) ? MIN(ZSTD_HASHLOG3_MAX, cParams->windowLog) : 0;
