2512|        assert(srcCCtx->appliedParams.useBlockSplitter != ZSTD_ps_auto);
2513|        assert(srcCCtx->appliedParams.ldmParams.enableLdm != ZSTD_ps_auto);
2514|        params.useRowMatchFinder = srcCCtx->appliedParams.useRowMatchFinder;
2515|        params.useBlockSplitter = srcCCtx->appliedParams.useBlockSplitter;
2516|        params.ldmParams = srcCCtx->appliedParams.ldmParams;
2517|        params.fParams = fParams;
2518|        params.maxBlockSize = srcCCtx->appliedParams.maxBlockSize;
