2531|    /* copy tables */
2532|    {   size_t const chainSize = ZSTD_allocateChainTable(srcCCtx->appliedParams.cParams.strategy,
2533|                                                         srcCCtx->appliedParams.useRowMatchFinder,
2534|                                                         0 /* forDDSDict */)
2535|                                    ? ((size_t)1 << srcCCtx->appliedParams.cParams.chainLog)
2536|                                    : 0;
2537|        size_t const hSize =  (size_t)1 << srcCCtx->appliedParams.cParams.hashLog;
2538|        int const h3log = srcCCtx->blockState.matchState.hashLog3;
2539|        size_t const h3Size = h3log ? ((size_t)1 << h3log) : 0;
2540|
2541|        ZSTD_memcpy(dstCCtx->blockState.matchState.hashTable,
2542|               srcCCtx->blockState.matchState.hashTable,
2543|               hSize * sizeof(U32));
2544|        ZSTD_memcpy(dstCCtx->blockState.matchState.chainTable,
2545|               srcCCtx->blockState.matchState.chainTable,
2546|               chainSize * sizeof(U32));
