2590|#define ZSTD_ROWSIZE 16
2591|/*! ZSTD_reduceTable() :
2592| *  reduce table indexes by `reducerValue`, or squash to zero.
2593| *  PreserveMark preserves "unsorted mark" for btlazy2 strategy.
2594| *  It must be set to a clear 0/1 value, to remove branch during inlining.
2595| *  Presume table size is a multiple of ZSTD_ROWSIZE
2596| *  to help auto-vectorization */
2597|FORCE_INLINE_TEMPLATE void
2598|ZSTD_reduceTable_internal (U32* const table, U32 const size, U32 const reducerValue, int const preserveMark)
2599|{
2600|    int const nbRows = (int)size / ZSTD_ROWSIZE;
2601|    int cellNb = 0;
2602|    int rowNb;
2603|    /* Protect special index values < ZSTD_WINDOW_START_INDEX. */
2604|    U32 const reducerThreshold = reducerValue + ZSTD_WINDOW_START_INDEX;
2605|    assert((size & (ZSTD_ROWSIZE-1)) == 0);  /* multiple of ZSTD_ROWSIZE */
2606|    assert(size < (1U<<31));   /* can be casted to int */
2607|
2608|#if ZSTD_MEMORY_SANITIZER && !defined (ZSTD_MSAN_DONT_POISON_WORKSPACE)
2609|    /* To validate that the table re-use logic is sound, and that we don't
2610|     * access table space that we haven't cleaned, we re-"poison" the table
2611|     * space every time we mark it dirty.
2612|     *
2613|     * This function however is intended to operate on those dirty tables and
2614|     * re-clean them. So when this function is used correctly, we can unpoison
2615|     * the memory it operated on. This introduces a blind spot though, since
2616|     * if we now try to operate on __actually__ poisoned memory, we will not
2617|     * detect that. */
2618|    __msan_unpoison(table, size * sizeof(U32));
2619|#endif
2620|
2621|    for (rowNb=0 ; rowNb < nbRows ; rowNb++) {
2622|        int column;
2623|        for (column=0; column<ZSTD_ROWSIZE; column++) {
2624|            U32 newVal;
2625|            if (preserveMark && table[cellNb] == ZSTD_DUBT_UNSORTED_MARK) {
2626|                /* This write is pointless, but is required(?) for the compiler
2627|                 * to auto-vectorize the loop. */
2628|                newVal = ZSTD_DUBT_UNSORTED_MARK;
2629|            } else if (table[cellNb] < reducerThreshold) {
2630|                newVal = 0;
2631|            } else {
2632|                newVal = table[cellNb] - reducerValue;
2633|            }
2634|            table[cellNb] = newVal;
2635|            cellNb++;
2636|    }   }
2637|}
2638|
2639|static void ZSTD_reduceTable(U32* const table, U32 const size, U32 const reducerValue)
2640|{
2641|    ZSTD_reduceTable_internal(table, size, reducerValue, 0);
2642|}
2643|
2644|static void ZSTD_reduceTable_btlazy2(U32* const table, U32 const size, U32 const reducerValue)
2645|{
2646|    ZSTD_reduceTable_internal(table, size, reducerValue, 1);
2647|}
