2649|/*! ZSTD_reduceIndex() :
2650|*   rescale all indexes to avoid future overflow (indexes are U32) */
2651|static void ZSTD_reduceIndex (ZSTD_matchState_t* ms, ZSTD_CCtx_params const* params, const U32 reducerValue)
2652|{
2653|    {   U32 const hSize = (U32)1 << params->cParams.hashLog;
2654|        ZSTD_reduceTable(ms->hashTable, hSize, reducerValue);
2655|    }
2656|
2657|    if (ZSTD_allocateChainTable(params->cParams.strategy, params->useRowMatchFinder, (U32)ms->dedicatedDictSearch)) {
2658|        U32 const chainSize = (U32)1 << params->cParams.chainLog;
2659|        if (params->cParams.strategy == ZSTD_btlazy2)
2660|            ZSTD_reduceTable_btlazy2(ms->chainTable, chainSize, reducerValue);
2661|        else
2662|            ZSTD_reduceTable(ms->chainTable, chainSize, reducerValue);
2663|    }
2664|
2665|    if (ms->hashLog3) {
2666|        U32 const h3Size = (U32)1 << ms->hashLog3;
2667|        ZSTD_reduceTable(ms->hashTable3, h3Size, reducerValue);
2668|    }
