2676|/* See doc/zstd_compression_format.md for detailed format description */
2677|
2678|int ZSTD_seqToCodes(const seqStore_t* seqStorePtr)
2679|{
2680|    const seqDef* const sequences = seqStorePtr->sequencesStart;
2681|    BYTE* const llCodeTable = seqStorePtr->llCode;
2682|    BYTE* const ofCodeTable = seqStorePtr->ofCode;
2683|    BYTE* const mlCodeTable = seqStorePtr->mlCode;
2684|    U32 const nbSeq = (U32)(seqStorePtr->sequences - seqStorePtr->sequencesStart);
2685|    U32 u;
2686|    int longOffsets = 0;
2687|    assert(nbSeq <= seqStorePtr->maxNbSeq);
2688|    for (u=0; u<nbSeq; u++) {
2689|        U32 const llv = sequences[u].litLength;
2690|        U32 const ofCode = ZSTD_highbit32(sequences[u].offBase);
2691|        U32 const mlv = sequences[u].mlBase;
2692|        llCodeTable[u] = (BYTE)ZSTD_LLcode(llv);
2693|        ofCodeTable[u] = (BYTE)ofCode;
2694|        mlCodeTable[u] = (BYTE)ZSTD_MLcode(mlv);
2695|        assert(!(MEM_64bits() && ofCode >= STREAM_ACCUMULATOR_MIN));
2696|        if (MEM_32bits() && ofCode >= STREAM_ACCUMULATOR_MIN)
2697|            longOffsets = 1;
2698|    }
2699|    if (seqStorePtr->longLengthType==ZSTD_llt_literalLength)
2700|        llCodeTable[seqStorePtr->longLengthPos] = MaxLL;
2701|    if (seqStorePtr->longLengthType==ZSTD_llt_matchLength)
2702|        mlCodeTable[seqStorePtr->longLengthPos] = MaxML;
2703|    return longOffsets;
