2728|/* Type returned by ZSTD_buildSequencesStatistics containing finalized symbol encoding types
2729| * and size of the sequences statistics
2730| */
2731|typedef struct {
2732|    U32 LLtype;
2733|    U32 Offtype;
2734|    U32 MLtype;
2735|    size_t size;
2736|    size_t lastCountSize; /* Accounts for bug in 1.3.4. More detail in ZSTD_entropyCompressSeqStore_internal() */
2737|    int longOffsets;
