2740|/* ZSTD_buildSequencesStatistics():
2741| * Returns a ZSTD_symbolEncodingTypeStats_t, or a zstd error code in the `size` field.
2742| * Modifies `nextEntropy` to have the appropriate values as a side effect.
2743| * nbSeq must be greater than 0.
2744| *
2745| * entropyWkspSize must be of size at least ENTROPY_WORKSPACE_SIZE - (MaxSeq + 1)*sizeof(U32)
2746| */
2747|static ZSTD_symbolEncodingTypeStats_t
2748|ZSTD_buildSequencesStatistics(
2749|                const seqStore_t* seqStorePtr, size_t nbSeq,
2750|                const ZSTD_fseCTables_t* prevEntropy, ZSTD_fseCTables_t* nextEntropy,
2751|                      BYTE* dst, const BYTE* const dstEnd,
2752|                      ZSTD_strategy strategy, unsigned* countWorkspace,
2753|                      void* entropyWorkspace, size_t entropyWkspSize)
2754|{
2755|    BYTE* const ostart = dst;
2756|    const BYTE* const oend = dstEnd;
2757|    BYTE* op = ostart;
2758|    FSE_CTable* CTable_LitLength = nextEntropy->litlengthCTable;
2759|    FSE_CTable* CTable_OffsetBits = nextEntropy->offcodeCTable;
2760|    FSE_CTable* CTable_MatchLength = nextEntropy->matchlengthCTable;
2761|    const BYTE* const ofCodeTable = seqStorePtr->ofCode;
2762|    const BYTE* const llCodeTable = seqStorePtr->llCode;
2763|    const BYTE* const mlCodeTable = seqStorePtr->mlCode;
2764|    ZSTD_symbolEncodingTypeStats_t stats;
2765|
2766|    stats.lastCountSize = 0;
2767|    /* convert length/distances into codes */
2768|    stats.longOffsets = ZSTD_seqToCodes(seqStorePtr);
2769|    assert(op <= oend);
2770|    assert(nbSeq != 0); /* ZSTD_selectEncodingType() divides by nbSeq */
