2772|    {   unsigned max = MaxLL;
2773|        size_t const mostFrequent = HIST_countFast_wksp(countWorkspace, &max, llCodeTable, nbSeq, entropyWorkspace, entropyWkspSize);   /* can't fail */
2774|        DEBUGLOG(5, "Building LL table");
2775|        nextEntropy->litlength_repeatMode = prevEntropy->litlength_repeatMode;
2776|        stats.LLtype = ZSTD_selectEncodingType(&nextEntropy->litlength_repeatMode,
2777|                                        countWorkspace, max, mostFrequent, nbSeq,
2778|                                        LLFSELog, prevEntropy->litlengthCTable,
2779|                                        LL_defaultNorm, LL_defaultNormLog,
2780|                                        ZSTD_defaultAllowed, strategy);
