2782|        assert(!(stats.LLtype < set_compressed && nextEntropy->litlength_repeatMode != FSE_repeat_none)); /* We don't copy tables */
2783|        {   size_t const countSize = ZSTD_buildCTable(
2784|                op, (size_t)(oend - op),
2785|                CTable_LitLength, LLFSELog, (symbolEncodingType_e)stats.LLtype,
2786|                countWorkspace, max, llCodeTable, nbSeq,
2787|                LL_defaultNorm, LL_defaultNormLog, MaxLL,
2788|                prevEntropy->litlengthCTable,
2789|                sizeof(prevEntropy->litlengthCTable),
2790|                entropyWorkspace, entropyWkspSize);
2791|            if (ZSTD_isError(countSize)) {
2792|                DEBUGLOG(3, "ZSTD_buildCTable for LitLens failed");
2793|                stats.size = countSize;
2794|                return stats;
2795|            }
2796|            if (stats.LLtype == set_compressed)
2797|                stats.lastCountSize = countSize;
2798|            op += countSize;
2799|            assert(op <= oend);
2800|    }   }
2801|    /* build CTable for Offsets */
2802|    {   unsigned max = MaxOff;
2803|        size_t const mostFrequent = HIST_countFast_wksp(
2804|            countWorkspace, &max, ofCodeTable, nbSeq, entropyWorkspace, entropyWkspSize);  /* can't fail */
2805|        /* We can only use the basic table if max <= DefaultMaxOff, otherwise the offsets are too large */
2806|        ZSTD_defaultPolicy_e const defaultPolicy = (max <= DefaultMaxOff) ? ZSTD_defaultAllowed : ZSTD_defaultDisallowed;
2807|        DEBUGLOG(5, "Building OF table");
2808|        nextEntropy->offcode_repeatMode = prevEntropy->offcode_repeatMode;
2809|        stats.Offtype = ZSTD_selectEncodingType(&nextEntropy->offcode_repeatMode,
2810|                                        countWorkspace, max, mostFrequent, nbSeq,
2811|                                        OffFSELog, prevEntropy->offcodeCTable,
2812|                                        OF_defaultNorm, OF_defaultNormLog,
2813|                                        defaultPolicy, strategy);
2814|        assert(!(stats.Offtype < set_compressed && nextEntropy->offcode_repeatMode != FSE_repeat_none)); /* We don't copy tables */
2815|        {   size_t const countSize = ZSTD_buildCTable(
2816|                op, (size_t)(oend - op),
2817|                CTable_OffsetBits, OffFSELog, (symbolEncodingType_e)stats.Offtype,
2818|                countWorkspace, max, ofCodeTable, nbSeq,
2819|                OF_defaultNorm, OF_defaultNormLog, DefaultMaxOff,
2820|                prevEntropy->offcodeCTable,
2821|                sizeof(prevEntropy->offcodeCTable),
2822|                entropyWorkspace, entropyWkspSize);
2823|            if (ZSTD_isError(countSize)) {
2824|                DEBUGLOG(3, "ZSTD_buildCTable for Offsets failed");
2825|                stats.size = countSize;
2826|                return stats;
2827|            }
2828|            if (stats.Offtype == set_compressed)
2829|                stats.lastCountSize = countSize;
2830|            op += countSize;
2831|            assert(op <= oend);
2832|    }   }
2833|    /* build CTable for MatchLengths */
2834|    {   unsigned max = MaxML;
2835|        size_t const mostFrequent = HIST_countFast_wksp(
2836|            countWorkspace, &max, mlCodeTable, nbSeq, entropyWorkspace, entropyWkspSize);   /* can't fail */
2837|        DEBUGLOG(5, "Building ML table (remaining space : %i)", (int)(oend-op));
2838|        nextEntropy->matchlength_repeatMode = prevEntropy->matchlength_repeatMode;
2839|        stats.MLtype = ZSTD_selectEncodingType(&nextEntropy->matchlength_repeatMode,
2840|                                        countWorkspace, max, mostFrequent, nbSeq,
2841|                                        MLFSELog, prevEntropy->matchlengthCTable,
2842|                                        ML_defaultNorm, ML_defaultNormLog,
2843|                                        ZSTD_defaultAllowed, strategy);
2844|        assert(!(stats.MLtype < set_compressed && nextEntropy->matchlength_repeatMode != FSE_repeat_none)); /* We don't copy tables */
2845|        {   size_t const countSize = ZSTD_buildCTable(
2846|                op, (size_t)(oend - op),
2847|                CTable_MatchLength, MLFSELog, (symbolEncodingType_e)stats.MLtype,
2848|                countWorkspace, max, mlCodeTable, nbSeq,
2849|                ML_defaultNorm, ML_defaultNormLog, MaxML,
2850|                prevEntropy->matchlengthCTable,
2851|                sizeof(prevEntropy->matchlengthCTable),
2852|                entropyWorkspace, entropyWkspSize);
2853|            if (ZSTD_isError(countSize)) {
2854|                DEBUGLOG(3, "ZSTD_buildCTable for MatchLengths failed");
2855|                stats.size = countSize;
2856|                return stats;
2857|            }
2858|            if (stats.MLtype == set_compressed)
2859|                stats.lastCountSize = countSize;
2860|            op += countSize;
2861|            assert(op <= oend);
