2867|/* ZSTD_entropyCompressSeqStore_internal():
2868| * compresses both literals and sequences
2869| * Returns compressed size of block, or a zstd error.
2870| */
2871|#define SUSPECT_UNCOMPRESSIBLE_LITERAL_RATIO 20
2872|MEM_STATIC size_t
2873|ZSTD_entropyCompressSeqStore_internal(
2874|                        const seqStore_t* seqStorePtr,
2875|                        const ZSTD_entropyCTables_t* prevEntropy,
2876|                              ZSTD_entropyCTables_t* nextEntropy,
2877|                        const ZSTD_CCtx_params* cctxParams,
2878|                              void* dst, size_t dstCapacity,
2879|                              void* entropyWorkspace, size_t entropyWkspSize,
2880|                        const int bmi2)
