3180|/* ZSTD_fastSequenceLengthSum() :
3181| * Returns sum(litLen) + sum(matchLen) + lastLits for *seqBuf*.
3182| * Similar to another function in zstd_compress.c (determine_blockSize),
3183| * except it doesn't check for a block delimiter to end summation.
3184| * Removing the early exit allows the compiler to auto-vectorize (https://godbolt.org/z/cY1cajz9P).
3185| * This function can be deleted and replaced by determine_blockSize after we resolve issue #3456. */
3186|static size_t ZSTD_fastSequenceLengthSum(ZSTD_Sequence const* seqBuf, size_t seqBufSize) {
3187|    size_t matchLenSum, litLenSum, i;
3188|    matchLenSum = 0;
3189|    litLenSum = 0;
3190|    for (i = 0; i < seqBufSize; i++) {
3191|        litLenSum += seqBuf[i].litLength;
3192|        matchLenSum += seqBuf[i].matchLength;
3193|    }
3194|    return litLenSum + matchLenSum;
