3467|/* Unrolled loop to read four size_ts of input at a time. Returns 1 if is RLE, 0 if not. */
3468|static int ZSTD_isRLE(const BYTE* src, size_t length) {
3469|    const BYTE* ip = src;
3470|    const BYTE value = ip[0];
3471|    const size_t valueST = (size_t)((U64)value * 0x0101010101010101ULL);
3472|    const size_t unrollSize = sizeof(size_t) * 4;
3473|    const size_t unrollMask = unrollSize - 1;
3474|    const size_t prefixLength = length & unrollMask;
3475|    size_t i;
3476|    if (length == 1) return 1;
3477|    /* Check if prefix is RLE first before using unrolled loop */
3478|    if (prefixLength && ZSTD_count(ip+1, ip, ip+prefixLength) != prefixLength-1) {
3479|        return 0;
3480|    }
3481|    for (i = prefixLength; i != length; i += unrollSize) {
3482|        size_t u;
3483|        for (u = 0; u < unrollSize; u += sizeof(size_t)) {
3484|            if (MEM_readST(ip + i + u) != valueST) {
3485|                return 0;
3486|    }   }   }
3487|    return 1;
3488|}
