3521|/** ZSTD_buildBlockEntropyStats_literals() :
3522| *  Builds entropy for the literals.
3523| *  Stores literals block type (raw, rle, compressed, repeat) and
3524| *  huffman description table to hufMetadata.
3525| *  Requires ENTROPY_WORKSPACE_SIZE workspace
3526| * @return : size of huffman description table, or an error code
3527| */
3528|static size_t
3529|ZSTD_buildBlockEntropyStats_literals(void* const src, size_t srcSize,
3530|                               const ZSTD_hufCTables_t* prevHuf,
3531|                                     ZSTD_hufCTables_t* nextHuf,
3532|                                     ZSTD_hufCTablesMetadata_t* hufMetadata,
3533|                               const int literalsCompressionIsDisabled,
3534|                                     void* workspace, size_t wkspSize,
3535|                                     int hufFlags)
3536|{
3537|    BYTE* const wkspStart = (BYTE*)workspace;
3538|    BYTE* const wkspEnd = wkspStart + wkspSize;
3539|    BYTE* const countWkspStart = wkspStart;
3540|    unsigned* const countWksp = (unsigned*)workspace;
3541|    const size_t countWkspSize = (HUF_SYMBOLVALUE_MAX + 1) * sizeof(unsigned);
3542|    BYTE* const nodeWksp = countWkspStart + countWkspSize;
3543|    const size_t nodeWkspSize = (size_t)(wkspEnd - nodeWksp);
3544|    unsigned maxSymbolValue = HUF_SYMBOLVALUE_MAX;
3545|    unsigned huffLog = LitHufLog;
3546|    HUF_repeat repeat = prevHuf->repeatMode;
3547|    DEBUGLOG(5, "ZSTD_buildBlockEntropyStats_literals (srcSize=%zu)", srcSize);
3548|
3549|    /* Prepare nextEntropy assuming reusing the existing table */
3550|    ZSTD_memcpy(nextHuf, prevHuf, sizeof(*prevHuf));
3551|
3552|    if (literalsCompressionIsDisabled) {
3553|        DEBUGLOG(5, "set_basic - disabled");
3554|        hufMetadata->hType = set_basic;
3555|        return 0;
3556|    }
3557|
3558|    /* small ? don't even attempt compression (speed opt) */
3559|#ifndef COMPRESS_LITERALS_SIZE_MIN
3560|# define COMPRESS_LITERALS_SIZE_MIN 63  /* heuristic */
3561|#endif
3562|    {   size_t const minLitSize = (prevHuf->repeatMode == HUF_repeat_valid) ? 6 : COMPRESS_LITERALS_SIZE_MIN;
3563|        if (srcSize <= minLitSize) {
3564|            DEBUGLOG(5, "set_basic - too small");
3565|            hufMetadata->hType = set_basic;
3566|            return 0;
3567|    }   }
3568|
3569|    /* Scan input and build symbol stats */
3570|    {   size_t const largest =
3571|            HIST_count_wksp (countWksp, &maxSymbolValue,
3572|                            (const BYTE*)src, srcSize,
3573|                            workspace, wkspSize);
3574|        FORWARD_IF_ERROR(largest, "HIST_count_wksp failed");
3575|        if (largest == srcSize) {
3576|            /* only one literal symbol */
3577|            DEBUGLOG(5, "set_rle");
3578|            hufMetadata->hType = set_rle;
3579|            return 0;
3580|        }
3581|        if (largest <= (srcSize >> 7)+4) {
3582|            /* heuristic: likely not compressible */
3583|            DEBUGLOG(5, "set_basic - no gain");
3584|            hufMetadata->hType = set_basic;
3585|            return 0;
3586|    }   }
3587|
3588|    /* Validate the previous Huffman table */
3589|    if (repeat == HUF_repeat_check
3590|      && !HUF_validateCTable((HUF_CElt const*)prevHuf->CTable, countWksp, maxSymbolValue)) {
3591|        repeat = HUF_repeat_none;
3592|    }
3593|
3594|    /* Build Huffman Tree */
3595|    ZSTD_memset(nextHuf->CTable, 0, sizeof(nextHuf->CTable));
3596|    huffLog = HUF_optimalTableLog(huffLog, srcSize, maxSymbolValue, nodeWksp, nodeWkspSize, nextHuf->CTable, countWksp, hufFlags);
3597|    assert(huffLog <= LitHufLog);
3598|    {   size_t const maxBits = HUF_buildCTable_wksp((HUF_CElt*)nextHuf->CTable, countWksp,
3599|                                                    maxSymbolValue, huffLog,
3600|                                                    nodeWksp, nodeWkspSize);
3601|        FORWARD_IF_ERROR(maxBits, "HUF_buildCTable_wksp");
3602|        huffLog = (U32)maxBits;
3603|    }
3604|    {   /* Build and write the CTable */
3605|        size_t const newCSize = HUF_estimateCompressedSize(
3606|                (HUF_CElt*)nextHuf->CTable, countWksp, maxSymbolValue);
3607|        size_t const hSize = HUF_writeCTable_wksp(
3608|                hufMetadata->hufDesBuffer, sizeof(hufMetadata->hufDesBuffer),
3609|                (HUF_CElt*)nextHuf->CTable, maxSymbolValue, huffLog,
3610|                nodeWksp, nodeWkspSize);
3611|        /* Check against repeating the previous CTable */
3612|        if (repeat != HUF_repeat_none) {
3613|            size_t const oldCSize = HUF_estimateCompressedSize(
3614|                    (HUF_CElt const*)prevHuf->CTable, countWksp, maxSymbolValue);
3615|            if (oldCSize < srcSize && (oldCSize <= hSize + newCSize || hSize + 12 >= srcSize)) {
3616|                DEBUGLOG(5, "set_repeat - smaller");
3617|                ZSTD_memcpy(nextHuf, prevHuf, sizeof(*prevHuf));
3618|                hufMetadata->hType = set_repeat;
3619|                return 0;
3620|        }   }
3621|        if (newCSize + hSize >= srcSize) {
3622|            DEBUGLOG(5, "set_basic - no gains");
3623|            ZSTD_memcpy(nextHuf, prevHuf, sizeof(*prevHuf));
3624|            hufMetadata->hType = set_basic;
3625|            return 0;
3626|        }
3627|        DEBUGLOG(5, "set_compressed (hSize=%u)", (U32)hSize);
3628|        hufMetadata->hType = set_compressed;
3629|        nextHuf->repeatMode = HUF_repeat_check;
3630|        return hSize;
3631|    }
3632|}
