3738|    else if (hufMetadata->hType == set_rle) return 1;
3739|    else if (hufMetadata->hType == set_compressed || hufMetadata->hType == set_repeat) {
3740|        size_t const largest = HIST_count_wksp (countWksp, &maxSymbolValue, (const BYTE*)literals, litSize, workspace, wkspSize);
3741|        if (ZSTD_isError(largest)) return litSize;
3742|        {   size_t cLitSizeEstimate = HUF_estimateCompressedSize((const HUF_CElt*)huf->CTable, countWksp, maxSymbolValue);
3743|            if (writeEntropy) cLitSizeEstimate += hufMetadata->hufDesSize;
3744|            if (!singleStream) cLitSizeEstimate += 6; /* multi-stream huffman uses 6-byte jump table */
