3751|/* Returns the size estimate for the FSE-compressed symbols (of, ml, ll) of a block */
3752|static size_t
3753|ZSTD_estimateBlockSize_symbolType(symbolEncodingType_e type,
3754|                    const BYTE* codeTable, size_t nbSeq, unsigned maxCode,
3755|                    const FSE_CTable* fseCTable,
3756|                    const U8* additionalBits,
3757|                    short const* defaultNorm, U32 defaultNormLog, U32 defaultMax,
3758|                    void* workspace, size_t wkspSize)
3759|{
3760|    unsigned* const countWksp = (unsigned*)workspace;
3761|    const BYTE* ctp = codeTable;
3762|    const BYTE* const ctStart = ctp;
3763|    const BYTE* const ctEnd = ctStart + nbSeq;
3764|    size_t cSymbolTypeSizeEstimateInBits = 0;
3765|    unsigned max = maxCode;
3766|
3767|    HIST_countFast_wksp(countWksp, &max, codeTable, nbSeq, workspace, wkspSize);  /* can't fail */
3768|    if (type == set_basic) {
3769|        /* We selected this encoding type, so it must be valid. */
3770|        assert(max <= defaultMax);
3771|        (void)defaultMax;
3772|        cSymbolTypeSizeEstimateInBits = ZSTD_crossEntropyCost(defaultNorm, defaultNormLog, countWksp, max);
3773|    } else if (type == set_rle) {
3774|        cSymbolTypeSizeEstimateInBits = 0;
3775|    } else if (type == set_compressed || type == set_repeat) {
3776|        cSymbolTypeSizeEstimateInBits = ZSTD_fseBitCost(fseCTable, countWksp, max);
3777|    }
3778|    if (ZSTD_isError(cSymbolTypeSizeEstimateInBits)) {
3779|        return nbSeq * 10;
3780|    }
3781|    while (ctp < ctEnd) {
3782|        if (additionalBits) cSymbolTypeSizeEstimateInBits += additionalBits[*ctp];
3783|        else cSymbolTypeSizeEstimateInBits += *ctp; /* for offset, offset code is also the number of additional bits */
3784|        ctp++;
3785|    }
3786|    return cSymbolTypeSizeEstimateInBits >> 3;
