3864|/* Returns literals bytes represented in a seqStore */
3865|static size_t ZSTD_countSeqStoreLiteralsBytes(const seqStore_t* const seqStore)
3866|{
3867|    size_t literalsBytes = 0;
3868|    size_t const nbSeqs = (size_t)(seqStore->sequences - seqStore->sequencesStart);
3869|    size_t i;
3870|    for (i = 0; i < nbSeqs; ++i) {
3871|        seqDef const seq = seqStore->sequencesStart[i];
3872|        literalsBytes += seq.litLength;
3873|        if (i == seqStore->longLengthPos && seqStore->longLengthType == ZSTD_llt_literalLength) {
3874|            literalsBytes += 0x10000;
3875|    }   }
3876|    return literalsBytes;
3877|}
3878|
3879|/* Returns match bytes represented in a seqStore */
3880|static size_t ZSTD_countSeqStoreMatchBytes(const seqStore_t* const seqStore)
3881|{
3882|    size_t matchBytes = 0;
3883|    size_t const nbSeqs = (size_t)(seqStore->sequences - seqStore->sequencesStart);
3884|    size_t i;
3885|    for (i = 0; i < nbSeqs; ++i) {
3886|        seqDef seq = seqStore->sequencesStart[i];
3887|        matchBytes += seq.mlBase + MINMATCH;
3888|        if (i == seqStore->longLengthPos && seqStore->longLengthType == ZSTD_llt_matchLength) {
3889|            matchBytes += 0x10000;
3890|    }   }
3891|    return matchBytes;
