3894|/* Derives the seqStore that is a chunk of the originalSeqStore from [startIdx, endIdx).
3895| * Stores the result in resultSeqStore.
3896| */
3897|static void ZSTD_deriveSeqStoreChunk(seqStore_t* resultSeqStore,
3898|                               const seqStore_t* originalSeqStore,
3899|                                     size_t startIdx, size_t endIdx)
3900|{
3901|    *resultSeqStore = *originalSeqStore;
3902|    if (startIdx > 0) {
3903|        resultSeqStore->sequences = originalSeqStore->sequencesStart + startIdx;
3904|        resultSeqStore->litStart += ZSTD_countSeqStoreLiteralsBytes(resultSeqStore);
3905|    }
3906|
3907|    /* Move longLengthPos into the correct position if necessary */
3908|    if (originalSeqStore->longLengthType != ZSTD_llt_none) {
3909|        if (originalSeqStore->longLengthPos < startIdx || originalSeqStore->longLengthPos > endIdx) {
3910|            resultSeqStore->longLengthType = ZSTD_llt_none;
3911|        } else {
3912|            resultSeqStore->longLengthPos -= (U32)startIdx;
3913|        }
3914|    }
3915|    resultSeqStore->sequencesStart = originalSeqStore->sequencesStart + startIdx;
3916|    resultSeqStore->sequences = originalSeqStore->sequencesStart + endIdx;
3917|    if (endIdx == (size_t)(originalSeqStore->sequences - originalSeqStore->sequencesStart)) {
3918|        /* This accounts for possible last literals if the derived chunk reaches the end of the block */
3919|        assert(resultSeqStore->lit == originalSeqStore->lit);
3920|    } else {
3921|        size_t const literalsBytes = ZSTD_countSeqStoreLiteralsBytes(resultSeqStore);
3922|        resultSeqStore->lit = resultSeqStore->litStart + literalsBytes;
3923|    }
3924|    resultSeqStore->llCode += startIdx;
3925|    resultSeqStore->mlCode += startIdx;
3926|    resultSeqStore->ofCode += startIdx;
3927|}
