3929|/**
3930| * Returns the raw offset represented by the combination of offBase, ll0, and repcode history.
3931| * offBase must represent a repcode in the numeric representation of ZSTD_storeSeq().
3932| */
3933|static U32
3934|ZSTD_resolveRepcodeToRawOffset(const U32 rep[ZSTD_REP_NUM], const U32 offBase, const U32 ll0)
3935|{
3936|    U32 const adjustedRepCode = OFFBASE_TO_REPCODE(offBase) - 1 + ll0;  /* [ 0 - 3 ] */
3937|    assert(OFFBASE_IS_REPCODE(offBase));
3938|    if (adjustedRepCode == ZSTD_REP_NUM) {
3939|        assert(ll0);
3940|        /* litlength == 0 and offCode == 2 implies selection of first repcode - 1
3941|         * This is only valid if it results in a valid offset value, aka > 0.
3942|         * Note : it may happen that `rep[0]==1` in exceptional circumstances.
3943|         * In which case this function will return 0, which is an invalid offset.
3944|         * It's not an issue though, since this value will be
3945|         * compared and discarded within ZSTD_seqStore_resolveOffCodes().
3946|         */
3947|        return rep[0] - 1;
3948|    }
3949|    return rep[adjustedRepCode];
3950|}
