3952|/**
3953| * ZSTD_seqStore_resolveOffCodes() reconciles any possible divergences in offset history that may arise
3954| * due to emission of RLE/raw blocks that disturb the offset history,
3955| * and replaces any repcodes within the seqStore that may be invalid.
3956| *
3957| * dRepcodes are updated as would be on the decompression side.
3958| * cRepcodes are updated exactly in accordance with the seqStore.
3959| *
3960| * Note : this function assumes seq->offBase respects the following numbering scheme :
3961| *        0 : invalid
3962| *        1-3 : repcode 1-3
3963| *        4+ : real_offset+3
3964| */
3965|static void
3966|ZSTD_seqStore_resolveOffCodes(repcodes_t* const dRepcodes, repcodes_t* const cRepcodes,
3967|                        const seqStore_t* const seqStore, U32 const nbSeq)
3968|{
3969|    U32 idx = 0;
3970|    U32 const longLitLenIdx = seqStore->longLengthType == ZSTD_llt_literalLength ? seqStore->longLengthPos : nbSeq;
3971|    for (; idx < nbSeq; ++idx) {
3972|        seqDef* const seq = seqStore->sequencesStart + idx;
3973|        U32 const ll0 = (seq->litLength == 0) && (idx != longLitLenIdx);
3974|        U32 const offBase = seq->offBase;
3975|        assert(offBase > 0);
3976|        if (OFFBASE_IS_REPCODE(offBase)) {
3977|            U32 const dRawOffset = ZSTD_resolveRepcodeToRawOffset(dRepcodes->rep, offBase, ll0);
3978|            U32 const cRawOffset = ZSTD_resolveRepcodeToRawOffset(cRepcodes->rep, offBase, ll0);
3979|            /* Adjust simulated decompression repcode history if we come across a mismatch. Replace
3980|             * the repcode with the offset it actually references, determined by the compression
3981|             * repcode history.
3982|             */
3983|            if (dRawOffset != cRawOffset) {
3984|                seq->offBase = OFFSET_TO_OFFBASE(cRawOffset);
3985|            }
3986|        }
3987|        /* Compression repcode history is always updated with values directly from the unmodified seqStore.
3988|         * Decompression repcode history may use modified seq->offset value taken from compression repcode history.
3989|         */
3990|        ZSTD_updateRep(dRepcodes->rep, seq->offBase, ll0);
3991|        ZSTD_updateRep(cRepcodes->rep, offBase, ll0);
3992|    }
