4069|/* Struct to keep track of where we are in our recursive calls. */
4070|typedef struct {
4071|    U32* splitLocations;    /* Array of split indices */
4072|    size_t idx;             /* The current index within splitLocations being worked on */
4073|} seqStoreSplits;
4074|
4075|#define MIN_SEQUENCES_BLOCK_SPLITTING 300
4076|
4077|/* Helper function to perform the recursive search for block splits.
4078| * Estimates the cost of seqStore prior to split, and estimates the cost of splitting the sequences in half.
4079| * If advantageous to split, then we recurse down the two sub-blocks.
4080| * If not, or if an error occurred in estimation, then we do not recurse.
4081| *
4082| * Note: The recursion depth is capped by a heuristic minimum number of sequences,
4083| * defined by MIN_SEQUENCES_BLOCK_SPLITTING.
4084| * In theory, this means the absolute largest recursion depth is 10 == log2(maxNbSeqInBlock/MIN_SEQUENCES_BLOCK_SPLITTING).
4085| * In practice, recursion depth usually doesn't go beyond 4.
4086| *
4087| * Furthermore, the number of splits is capped by ZSTD_MAX_NB_BLOCK_SPLITS.
4088| * At ZSTD_MAX_NB_BLOCK_SPLITS == 196 with the current existing blockSize
4089| * maximum of 128 KB, this value is actually impossible to reach.
4090| */
4091|static void
4092|ZSTD_deriveBlockSplitsHelper(seqStoreSplits* splits, size_t startIdx, size_t endIdx,
4093|                             ZSTD_CCtx* zc, const seqStore_t* origSeqStore)
4094|{
4095|    seqStore_t* const fullSeqStoreChunk = &zc->blockSplitCtx.fullSeqStoreChunk;
4096|    seqStore_t* const firstHalfSeqStore = &zc->blockSplitCtx.firstHalfSeqStore;
4097|    seqStore_t* const secondHalfSeqStore = &zc->blockSplitCtx.secondHalfSeqStore;
4098|    size_t estimatedOriginalSize;
4099|    size_t estimatedFirstHalfSize;
4100|    size_t estimatedSecondHalfSize;
4101|    size_t midIdx = (startIdx + endIdx)/2;
4102|
4103|    DEBUGLOG(5, "ZSTD_deriveBlockSplitsHelper: startIdx=%zu endIdx=%zu", startIdx, endIdx);
4104|    assert(endIdx >= startIdx);
4105|    if (endIdx - startIdx < MIN_SEQUENCES_BLOCK_SPLITTING || splits->idx >= ZSTD_MAX_NB_BLOCK_SPLITS) {
4106|        DEBUGLOG(6, "ZSTD_deriveBlockSplitsHelper: Too few sequences (%zu)", endIdx - startIdx);
4107|        return;
4108|    }
4109|    ZSTD_deriveSeqStoreChunk(fullSeqStoreChunk, origSeqStore, startIdx, endIdx);
4110|    ZSTD_deriveSeqStoreChunk(firstHalfSeqStore, origSeqStore, startIdx, midIdx);
4111|    ZSTD_deriveSeqStoreChunk(secondHalfSeqStore, origSeqStore, midIdx, endIdx);
4112|    estimatedOriginalSize = ZSTD_buildEntropyStatisticsAndEstimateSubBlockSize(fullSeqStoreChunk, zc);
4113|    estimatedFirstHalfSize = ZSTD_buildEntropyStatisticsAndEstimateSubBlockSize(firstHalfSeqStore, zc);
4114|    estimatedSecondHalfSize = ZSTD_buildEntropyStatisticsAndEstimateSubBlockSize(secondHalfSeqStore, zc);
4115|    DEBUGLOG(5, "Estimated original block size: %zu -- First half split: %zu -- Second half split: %zu",
4116|             estimatedOriginalSize, estimatedFirstHalfSize, estimatedSecondHalfSize);
4117|    if (ZSTD_isError(estimatedOriginalSize) || ZSTD_isError(estimatedFirstHalfSize) || ZSTD_isError(estimatedSecondHalfSize)) {
4118|        return;
4119|    }
4120|    if (estimatedFirstHalfSize + estimatedSecondHalfSize < estimatedOriginalSize) {
4121|        DEBUGLOG(5, "split decided at seqNb:%zu", midIdx);
4122|        ZSTD_deriveBlockSplitsHelper(splits, startIdx, midIdx, zc, origSeqStore);
4123|        splits->splitLocations[splits->idx] = (U32)midIdx;
4124|        splits->idx++;
4125|        ZSTD_deriveBlockSplitsHelper(splits, midIdx, endIdx, zc, origSeqStore);
4126|    }
