4276|static size_t
4277|ZSTD_compressBlock_internal(ZSTD_CCtx* zc,
4278|                            void* dst, size_t dstCapacity,
4279|                            const void* src, size_t srcSize, U32 frame)
4280|{
4281|    /* This is an estimated upper bound for the length of an rle block.
4282|     * This isn't the actual upper bound.
4283|     * Finding the real threshold needs further investigation.
4284|     */
4285|    const U32 rleMaxLength = 25;
4286|    size_t cSize;
4287|    const BYTE* ip = (const BYTE*)src;
4288|    BYTE* op = (BYTE*)dst;
4289|    DEBUGLOG(5, "ZSTD_compressBlock_internal (dstCapacity=%u, dictLimit=%u, nextToUpdate=%u)",
4290|                (unsigned)dstCapacity, (unsigned)zc->blockState.matchState.window.dictLimit,
4291|                (unsigned)zc->blockState.matchState.nextToUpdate);
4292|
4293|    {   const size_t bss = ZSTD_buildSeqStore(zc, src, srcSize);
4294|        FORWARD_IF_ERROR(bss, "ZSTD_buildSeqStore failed");
4295|        if (bss == ZSTDbss_noCompress) { cSize = 0; goto out; }
4296|    }
4297|
4298|    if (zc->seqCollector.collectSequences) {
4299|        ZSTD_copyBlockSequences(zc);
4300|        ZSTD_blockState_confirmRepcodesAndEntropyTables(&zc->blockState);
4301|        return 0;
4302|    }
4303|
4304|    /* encode sequences and literals */
4305|    cSize = ZSTD_entropyCompressSeqStore(&zc->seqStore,
4306|            &zc->blockState.prevCBlock->entropy, &zc->blockState.nextCBlock->entropy,
4307|            &zc->appliedParams,
4308|            dst, dstCapacity,
4309|            srcSize,
4310|            zc->entropyWorkspace, ENTROPY_WORKSPACE_SIZE /* statically allocated in resetCCtx */,
4311|            zc->bmi2);
4312|
4313|    if (frame &&
4314|        /* We don't want to emit our first block as a RLE even if it qualifies because
4315|         * doing so will cause the decoder (cli only) to throw a "should consume all input error."
4316|         * This is only an issue for zstd <= v1.4.3
4317|         */
4318|        !zc->isFirstBlock &&
4319|        cSize < rleMaxLength &&
4320|        ZSTD_isRLE(ip, srcSize))
4321|    {
4322|        cSize = 1;
4323|        op[0] = ip[0];
4324|    }
4325|
4326|out:
4327|    if (!ZSTD_isError(cSize) && cSize > 1) {
4328|        ZSTD_blockState_confirmRepcodesAndEntropyTables(&zc->blockState);
4329|    }
4330|    /* We check that dictionaries have offset codes available for the first
4331|     * block. After the first block, the offcode table might not have large
4332|     * enough codes to represent the offsets in the data.
4333|     */
4334|    if (zc->blockState.prevCBlock->entropy.fse.offcode_repeatMode == FSE_repeat_valid)
4335|        zc->blockState.prevCBlock->entropy.fse.offcode_repeatMode = FSE_repeat_check;
4336|
4337|    return cSize;
