4340|static size_t ZSTD_compressBlock_targetCBlockSize_body(ZSTD_CCtx* zc,
4341|                               void* dst, size_t dstCapacity,
4342|                               const void* src, size_t srcSize,
4343|                               const size_t bss, U32 lastBlock)
4344|{
4345|    DEBUGLOG(6, "Attempting ZSTD_compressSuperBlock()");
4346|    if (bss == ZSTDbss_compress) {
4347|        if (/* We don't want to emit our first block as a RLE even if it qualifies because
4348|            * doing so will cause the decoder (cli only) to throw a "should consume all input error."
4349|            * This is only an issue for zstd <= v1.4.3
4350|            */
4351|            !zc->isFirstBlock &&
4352|            ZSTD_maybeRLE(&zc->seqStore) &&
4353|            ZSTD_isRLE((BYTE const*)src, srcSize))
4354|        {
4355|            return ZSTD_rleCompressBlock(dst, dstCapacity, *(BYTE const*)src, srcSize, lastBlock);
4356|        }
4357|        /* Attempt superblock compression.
4358|         *
4359|         * Note that compressed size of ZSTD_compressSuperBlock() is not bound by the
4360|         * standard ZSTD_compressBound(). This is a problem, because even if we have
4361|         * space now, taking an extra byte now could cause us to run out of space later
4362|         * and violate ZSTD_compressBound().
4363|         *
4364|         * Define blockBound(blockSize) = blockSize + ZSTD_blockHeaderSize.
4365|         *
4366|         * In order to respect ZSTD_compressBound() we must attempt to emit a raw
4367|         * uncompressed block in these cases:
4368|         *   * cSize == 0: Return code for an uncompressed block.
4369|         *   * cSize == dstSize_tooSmall: We may have expanded beyond blockBound(srcSize).
4370|         *     ZSTD_noCompressBlock() will return dstSize_tooSmall if we are really out of
4371|         *     output space.
4372|         *   * cSize >= blockBound(srcSize): We have expanded the block too much so
4373|         *     emit an uncompressed block.
4374|         */
4375|        {   size_t const cSize =
4376|                ZSTD_compressSuperBlock(zc, dst, dstCapacity, src, srcSize, lastBlock);
4377|            if (cSize != ERROR(dstSize_tooSmall)) {
4378|                size_t const maxCSize =
4379|                    srcSize - ZSTD_minGain(srcSize, zc->appliedParams.cParams.strategy);
4380|                FORWARD_IF_ERROR(cSize, "ZSTD_compressSuperBlock failed");
4381|                if (cSize != 0 && cSize < maxCSize + ZSTD_blockHeaderSize) {
4382|                    ZSTD_blockState_confirmRepcodesAndEntropyTables(&zc->blockState);
4383|                    return cSize;
4384|                }
4385|            }
4386|        }
4387|    } /* if (bss == ZSTDbss_compress)*/
4388|
4389|    DEBUGLOG(6, "Resorting to ZSTD_noCompressBlock()");
4390|    /* Superblock compression failed, attempt to emit a single no compress block.
4391|     * The decoder will be able to stream this block since it is uncompressed.
4392|     */
4393|    return ZSTD_noCompressBlock(dst, dstCapacity, src, srcSize, lastBlock);
4394|}
