4397|                               void* dst, size_t dstCapacity,
4398|                               const void* src, size_t srcSize,
4399|                               U32 lastBlock)
4400|{
4401|    size_t cSize = 0;
4402|    const size_t bss = ZSTD_buildSeqStore(zc, src, srcSize);
4403|    DEBUGLOG(5, "ZSTD_compressBlock_targetCBlockSize (dstCapacity=%u, dictLimit=%u, nextToUpdate=%u, srcSize=%zu)",
4404|                (unsigned)dstCapacity, (unsigned)zc->blockState.matchState.window.dictLimit, (unsigned)zc->blockState.matchState.nextToUpdate, srcSize);
4405|    FORWARD_IF_ERROR(bss, "ZSTD_buildSeqStore failed");
