4416|static void ZSTD_overflowCorrectIfNeeded(ZSTD_matchState_t* ms,
4417|                                         ZSTD_cwksp* ws,
4418|                                         ZSTD_CCtx_params const* params,
4419|                                         void const* ip,
4420|                                         void const* iend)
4421|{
4422|    U32 const cycleLog = ZSTD_cycleLog(params->cParams.chainLog, params->cParams.strategy);
4423|    U32 const maxDist = (U32)1 << params->cParams.windowLog;
4424|    if (ZSTD_window_needOverflowCorrection(ms->window, cycleLog, maxDist, ms->loadedDictEnd, ip, iend)) {
4425|        U32 const correction = ZSTD_window_correctOverflow(&ms->window, cycleLog, maxDist, ip);
4426|        ZSTD_STATIC_ASSERT(ZSTD_CHAINLOG_MAX <= 30);
4427|        ZSTD_STATIC_ASSERT(ZSTD_WINDOWLOG_MAX_32 <= 30);
4428|        ZSTD_STATIC_ASSERT(ZSTD_WINDOWLOG_MAX <= 31);
4429|        ZSTD_cwksp_mark_tables_dirty(ws);
4430|        ZSTD_reduceIndex(ms, params, correction);
4431|        ZSTD_cwksp_mark_tables_clean(ws);
4432|        if (ms->nextToUpdate < correction) ms->nextToUpdate = 0;
4433|        else ms->nextToUpdate -= correction;
4434|        /* invalidate dictionaries on overflow correction */
4435|        ms->loadedDictEnd = 0;
4436|        ms->dictMatchState = NULL;
4437|    }
