4440|/*! ZSTD_compress_frameChunk() :
4441|*   Compress a chunk of data into one or multiple blocks.
4442|*   All blocks will be terminated, all input will be consumed.
4443|*   Function will issue an error if there is not enough `dstCapacity` to hold the compressed content.
4444|*   Frame is supposed already started (header already produced)
4445|*  @return : compressed size, or an error code
4446|*/
4447|static size_t ZSTD_compress_frameChunk(ZSTD_CCtx* cctx,
4448|                                     void* dst, size_t dstCapacity,
4449|                               const void* src, size_t srcSize,
4450|                                     U32 lastFrameChunk)
4451|{
4452|    size_t blockSize = cctx->blockSize;
4453|    size_t remaining = srcSize;
4454|    const BYTE* ip = (const BYTE*)src;
4455|    BYTE* const ostart = (BYTE*)dst;
4456|    BYTE* op = ostart;
4457|    U32 const maxDist = (U32)1 << cctx->appliedParams.cParams.windowLog;
4458|
4459|    assert(cctx->appliedParams.cParams.windowLog <= ZSTD_WINDOWLOG_MAX);
4460|
4461|    DEBUGLOG(4, "ZSTD_compress_frameChunk (blockSize=%u)", (unsigned)blockSize);
4462|    if (cctx->appliedParams.fParams.checksumFlag && srcSize)
4463|        XXH64_update(&cctx->xxhState, src, srcSize);
4464|
4465|    while (remaining) {
4466|        ZSTD_matchState_t* const ms = &cctx->blockState.matchState;
4467|        U32 const lastBlock = lastFrameChunk & (blockSize >= remaining);
4468|
4469|        /* TODO: See 3090. We reduced MIN_CBLOCK_SIZE from 3 to 2 so to compensate we are adding
4470|         * additional 1. We need to revisit and change this logic to be more consistent */
4471|        RETURN_ERROR_IF(dstCapacity < ZSTD_blockHeaderSize + MIN_CBLOCK_SIZE + 1,
4472|                        dstSize_tooSmall,
4473|                        "not enough space to store compressed block");
4474|        if (remaining < blockSize) blockSize = remaining;
4475|
4476|        ZSTD_overflowCorrectIfNeeded(
4477|            ms, &cctx->workspace, &cctx->appliedParams, ip, ip + blockSize);
4478|        ZSTD_checkDictValidity(&ms->window, ip + blockSize, maxDist, &ms->loadedDictEnd, &ms->dictMatchState);
4479|        ZSTD_window_enforceMaxDist(&ms->window, ip, maxDist, &ms->loadedDictEnd, &ms->dictMatchState);
4480|
4481|        /* Ensure hash/chain table insertion resumes no sooner than lowlimit */
4482|        if (ms->nextToUpdate < ms->window.lowLimit) ms->nextToUpdate = ms->window.lowLimit;
4483|
4484|        {   size_t cSize;
4485|            if (ZSTD_useTargetCBlockSize(&cctx->appliedParams)) {
4486|                cSize = ZSTD_compressBlock_targetCBlockSize(cctx, op, dstCapacity, ip, blockSize, lastBlock);
4487|                FORWARD_IF_ERROR(cSize, "ZSTD_compressBlock_targetCBlockSize failed");
4488|                assert(cSize > 0);
4489|                assert(cSize <= blockSize + ZSTD_blockHeaderSize);
4490|            } else if (ZSTD_blockSplitterEnabled(&cctx->appliedParams)) {
4491|                cSize = ZSTD_compressBlock_splitBlock(cctx, op, dstCapacity, ip, blockSize, lastBlock);
4492|                FORWARD_IF_ERROR(cSize, "ZSTD_compressBlock_splitBlock failed");
4493|                assert(cSize > 0 || cctx->seqCollector.collectSequences == 1);
4494|            } else {
4495|                cSize = ZSTD_compressBlock_internal(cctx,
4496|                                        op+ZSTD_blockHeaderSize, dstCapacity-ZSTD_blockHeaderSize,
4497|                                        ip, blockSize, 1 /* frame */);
4498|                FORWARD_IF_ERROR(cSize, "ZSTD_compressBlock_internal failed");
4499|
4500|                if (cSize == 0) {  /* block is not compressible */
4501|                    cSize = ZSTD_noCompressBlock(op, dstCapacity, ip, blockSize, lastBlock);
4502|                    FORWARD_IF_ERROR(cSize, "ZSTD_noCompressBlock failed");
4503|                } else {
4504|                    U32 const cBlockHeader = cSize == 1 ?
4505|                        lastBlock + (((U32)bt_rle)<<1) + (U32)(blockSize << 3) :
4506|                        lastBlock + (((U32)bt_compressed)<<1) + (U32)(cSize << 3);
4507|                    MEM_writeLE24(op, cBlockHeader);
4508|                    cSize += ZSTD_blockHeaderSize;
4509|                }
4510|            }  /* if (ZSTD_useTargetCBlockSize(&cctx->appliedParams))*/
4511|
4512|
4513|            ip += blockSize;
4514|            assert(remaining >= blockSize);
4515|            remaining -= blockSize;
4516|            op += cSize;
4517|            assert(dstCapacity >= cSize);
4518|            dstCapacity -= cSize;
4519|            cctx->isFirstBlock = 0;
4520|            DEBUGLOG(5, "ZSTD_compress_frameChunk: adding a block of size %u",
4521|                        (unsigned)cSize);
4522|    }   }
4523|
4524|    if (lastFrameChunk && (op>ostart)) cctx->stage = ZSTDcs_ending;
4525|    return (size_t)(op-ostart);
4526|}
