4529|static size_t ZSTD_writeFrameHeader(void* dst, size_t dstCapacity,
4530|                                    const ZSTD_CCtx_params* params, U64 pledgedSrcSize, U32 dictID)
4531|{   BYTE* const op = (BYTE*)dst;
4532|    U32   const dictIDSizeCodeLength = (dictID>0) + (dictID>=256) + (dictID>=65536);   /* 0-3 */
4533|    U32   const dictIDSizeCode = params->fParams.noDictIDFlag ? 0 : dictIDSizeCodeLength;   /* 0-3 */
4534|    U32   const checksumFlag = params->fParams.checksumFlag>0;
4535|    U32   const windowSize = (U32)1 << params->cParams.windowLog;
4536|    U32   const singleSegment = params->fParams.contentSizeFlag && (windowSize >= pledgedSrcSize);
4537|    BYTE  const windowLogByte = (BYTE)((params->cParams.windowLog - ZSTD_WINDOWLOG_ABSOLUTEMIN) << 3);
4538|    U32   const fcsCode = params->fParams.contentSizeFlag ?
4539|                     (pledgedSrcSize>=256) + (pledgedSrcSize>=65536+256) + (pledgedSrcSize>=0xFFFFFFFFU) : 0;  /* 0-3 */
4540|    BYTE  const frameHeaderDescriptionByte = (BYTE)(dictIDSizeCode + (checksumFlag<<2) + (singleSegment<<5) + (fcsCode<<6) );
4541|    size_t pos=0;
4542|
4543|    assert(!(params->fParams.contentSizeFlag && pledgedSrcSize == ZSTD_CONTENTSIZE_UNKNOWN));
4544|    RETURN_ERROR_IF(dstCapacity < ZSTD_FRAMEHEADERSIZE_MAX, dstSize_tooSmall,
4545|                    "dst buf is too small to fit worst-case frame header size.");
4546|    DEBUGLOG(4, "ZSTD_writeFrameHeader : dictIDFlag : %u ; dictID : %u ; dictIDSizeCode : %u",
4547|                !params->fParams.noDictIDFlag, (unsigned)dictID, (unsigned)dictIDSizeCode);
4548|    if (params->format == ZSTD_f_zstd1) {
4549|        MEM_writeLE32(dst, ZSTD_MAGICNUMBER);
4550|        pos = 4;
4551|    }
4552|    op[pos++] = frameHeaderDescriptionByte;
4553|    if (!singleSegment) op[pos++] = windowLogByte;
4554|    switch(dictIDSizeCode)
4555|    {
4556|        default:
4557|            assert(0); /* impossible */
4558|            ZSTD_FALLTHROUGH;
4559|        case 0 : break;
4560|        case 1 : op[pos] = (BYTE)(dictID); pos++; break;
4561|        case 2 : MEM_writeLE16(op+pos, (U16)dictID); pos+=2; break;
4562|        case 3 : MEM_writeLE32(op+pos, dictID); pos+=4; break;
4563|    }
4564|    switch(fcsCode)
4565|    {
4566|        default:
4567|            assert(0); /* impossible */
4568|            ZSTD_FALLTHROUGH;
4569|        case 0 : if (singleSegment) op[pos++] = (BYTE)(pledgedSrcSize); break;
4570|        case 1 : MEM_writeLE16(op+pos, (U16)(pledgedSrcSize-256)); pos+=2; break;
4571|        case 2 : MEM_writeLE32(op+pos, (U32)(pledgedSrcSize)); pos+=4; break;
4572|        case 3 : MEM_writeLE64(op+pos, (U64)(pledgedSrcSize)); pos+=8; break;
4573|    }
4574|    return pos;
