4883|    if (dictMaxSymbolValue < maxSymbolValue) {
4884|        return FSE_repeat_check;
4885|    }
4886|    for (s = 0; s <= maxSymbolValue; ++s) {
4887|        if (normalizedCounter[s] == 0) {
4888|            return FSE_repeat_check;
4889|        }
4890|    }
4891|    return FSE_repeat_valid;
