4894|size_t ZSTD_loadCEntropy(ZSTD_compressedBlockState_t* bs, void* workspace,
4895|                         const void* const dict, size_t dictSize)
4896|{
4897|    short offcodeNCount[MaxOff+1];
4898|    unsigned offcodeMaxValue = MaxOff;
4899|    const BYTE* dictPtr = (const BYTE*)dict;    /* skip magic num and dict ID */
4900|    const BYTE* const dictEnd = dictPtr + dictSize;
4901|    dictPtr += 8;
4902|    bs->entropy.huf.repeatMode = HUF_repeat_check;
4903|
4904|    {   unsigned maxSymbolValue = 255;
4905|        unsigned hasZeroWeights = 1;
4906|        size_t const hufHeaderSize = HUF_readCTable((HUF_CElt*)bs->entropy.huf.CTable, &maxSymbolValue, dictPtr,
4907|            dictEnd-dictPtr, &hasZeroWeights);
4908|
4909|        /* We only set the loaded table as valid if it contains all non-zero
4910|         * weights. Otherwise, we set it to check */
4911|        if (!hasZeroWeights)
4912|            bs->entropy.huf.repeatMode = HUF_repeat_valid;
4913|
4914|        RETURN_ERROR_IF(HUF_isError(hufHeaderSize), dictionary_corrupted, "");
4915|        RETURN_ERROR_IF(maxSymbolValue < 255, dictionary_corrupted, "");
4916|        dictPtr += hufHeaderSize;
4917|    }
4918|
4919|    {   unsigned offcodeLog;
4920|        size_t const offcodeHeaderSize = FSE_readNCount(offcodeNCount, &offcodeMaxValue, &offcodeLog, dictPtr, dictEnd-dictPtr);
4921|        RETURN_ERROR_IF(FSE_isError(offcodeHeaderSize), dictionary_corrupted, "");
4922|        RETURN_ERROR_IF(offcodeLog > OffFSELog, dictionary_corrupted, "");
4923|        /* fill all offset symbols to avoid garbage at end of table */
4924|        RETURN_ERROR_IF(FSE_isError(FSE_buildCTable_wksp(
4925|                bs->entropy.fse.offcodeCTable,
4926|                offcodeNCount, MaxOff, offcodeLog,
4927|                workspace, HUF_WORKSPACE_SIZE)),
4928|            dictionary_corrupted, "");
4929|        /* Defer checking offcodeMaxValue because we need to know the size of the dictionary content */
4930|        dictPtr += offcodeHeaderSize;
4931|    }
4932|
4933|    {   short matchlengthNCount[MaxML+1];
4934|        unsigned matchlengthMaxValue = MaxML, matchlengthLog;
4935|        size_t const matchlengthHeaderSize = FSE_readNCount(matchlengthNCount, &matchlengthMaxValue, &matchlengthLog, dictPtr, dictEnd-dictPtr);
4936|        RETURN_ERROR_IF(FSE_isError(matchlengthHeaderSize), dictionary_corrupted, "");
4937|        RETURN_ERROR_IF(matchlengthLog > MLFSELog, dictionary_corrupted, "");
4938|        RETURN_ERROR_IF(FSE_isError(FSE_buildCTable_wksp(
4939|                bs->entropy.fse.matchlengthCTable,
4940|                matchlengthNCount, matchlengthMaxValue, matchlengthLog,
4941|                workspace, HUF_WORKSPACE_SIZE)),
4942|            dictionary_corrupted, "");
4943|        bs->entropy.fse.matchlength_repeatMode = ZSTD_dictNCountRepeat(matchlengthNCount, matchlengthMaxValue, MaxML);
4944|        dictPtr += matchlengthHeaderSize;
4945|    }
4946|
4947|    {   short litlengthNCount[MaxLL+1];
4948|        unsigned litlengthMaxValue = MaxLL, litlengthLog;
4949|        size_t const litlengthHeaderSize = FSE_readNCount(litlengthNCount, &litlengthMaxValue, &litlengthLog, dictPtr, dictEnd-dictPtr);
4950|        RETURN_ERROR_IF(FSE_isError(litlengthHeaderSize), dictionary_corrupted, "");
4951|        RETURN_ERROR_IF(litlengthLog > LLFSELog, dictionary_corrupted, "");
4952|        RETURN_ERROR_IF(FSE_isError(FSE_buildCTable_wksp(
4953|                bs->entropy.fse.litlengthCTable,
4954|                litlengthNCount, litlengthMaxValue, litlengthLog,
4955|                workspace, HUF_WORKSPACE_SIZE)),
4956|            dictionary_corrupted, "");
4957|        bs->entropy.fse.litlength_repeatMode = ZSTD_dictNCountRepeat(litlengthNCount, litlengthMaxValue, MaxLL);
4958|        dictPtr += litlengthHeaderSize;
4959|    }
4960|
4961|    RETURN_ERROR_IF(dictPtr+12 > dictEnd, dictionary_corrupted, "");
4962|    bs->rep[0] = MEM_readLE32(dictPtr+0);
4963|    bs->rep[1] = MEM_readLE32(dictPtr+4);
4964|    bs->rep[2] = MEM_readLE32(dictPtr+8);
4965|    dictPtr += 12;
4966|
4967|    {   size_t const dictContentSize = (size_t)(dictEnd - dictPtr);
4968|        U32 offcodeMax = MaxOff;
4969|        if (dictContentSize <= ((U32)-1) - 128 KB) {
4970|            U32 const maxOffset = (U32)dictContentSize + 128 KB; /* The maximum offset that must be supported */
