4978|            for (u=0; u<3; u++) {
4979|                RETURN_ERROR_IF(bs->rep[u] == 0, dictionary_corrupted, "");
4980|                RETURN_ERROR_IF(bs->rep[u] > dictContentSize, dictionary_corrupted, "");
4981|    }   }   }
4982|
4983|    return dictPtr - (const BYTE*)dict;
