5175|/*! ZSTD_writeEpilogue() :
5176|*   Ends a frame.
5177|*   @return : nb of bytes written into dst (or an error code) */
5178|static size_t ZSTD_writeEpilogue(ZSTD_CCtx* cctx, void* dst, size_t dstCapacity)
5179|{
5180|    BYTE* const ostart = (BYTE*)dst;
5181|    BYTE* op = ostart;
5182|    size_t fhSize = 0;
5183|
5184|    DEBUGLOG(4, "ZSTD_writeEpilogue");
5185|    RETURN_ERROR_IF(cctx->stage == ZSTDcs_created, stage_wrong, "init missing");
5186|
5187|    /* special case : empty frame */
5188|    if (cctx->stage == ZSTDcs_init) {
5189|        fhSize = ZSTD_writeFrameHeader(dst, dstCapacity, &cctx->appliedParams, 0, 0);
5190|        FORWARD_IF_ERROR(fhSize, "ZSTD_writeFrameHeader failed");
5191|        dstCapacity -= fhSize;
5192|        op += fhSize;
5193|        cctx->stage = ZSTDcs_ongoing;
5194|    }
5195|
5196|    if (cctx->stage != ZSTDcs_ending) {
5197|        /* write one last empty block, make it the "last" block */
5198|        U32 const cBlockHeader24 = 1 /* last block */ + (((U32)bt_raw)<<1) + 0;
5199|        RETURN_ERROR_IF(dstCapacity<4, dstSize_tooSmall, "no room for epilogue");
5200|        MEM_writeLE32(op, cBlockHeader24);
5201|        op += ZSTD_blockHeaderSize;
5202|        dstCapacity -= ZSTD_blockHeaderSize;
5203|    }
5204|
5205|    if (cctx->appliedParams.fParams.checksumFlag) {
5206|        U32 const checksum = (U32) XXH64_digest(&cctx->xxhState);
5207|        RETURN_ERROR_IF(dstCapacity<4, dstSize_tooSmall, "no room for checksum");
5208|        DEBUGLOG(4, "ZSTD_writeEpilogue: write checksum : %08X", (unsigned)checksum);
5209|        MEM_writeLE32(op, checksum);
5210|        op += 4;
5211|    }
5212|
5213|    cctx->stage = ZSTDcs_created;  /* return to "created but no init" status */
5214|    return op-ostart;
