5660|    DEBUGLOG(4, "ZSTD_compressBegin_usingCDict_internal");
5661|    RETURN_ERROR_IF(cdict==NULL, dictionary_wrong, "NULL pointer!");
5662|    /* Initialize the cctxParams from the cdict */
5663|    {
5664|        ZSTD_parameters params;
5665|        params.fParams = fParams;
5666|        params.cParams = ( pledgedSrcSize < ZSTD_USE_CDICT_PARAMS_SRCSIZE_CUTOFF
