5932|/** ZSTD_compressStream_generic():
5933| *  internal function for all *compressStream*() variants
5934| * @return : hint size for next input to complete ongoing block */
5935|static size_t ZSTD_compressStream_generic(ZSTD_CStream* zcs,
5936|                                          ZSTD_outBuffer* output,
5937|                                          ZSTD_inBuffer* input,
5938|                                          ZSTD_EndDirective const flushMode)
5939|{
5940|    const char* const istart = (assert(input != NULL), (const char*)input->src);
5941|    const char* const iend = (istart != NULL) ? istart + input->size : istart;
5942|    const char* ip = (istart != NULL) ? istart + input->pos : istart;
5943|    char* const ostart = (assert(output != NULL), (char*)output->dst);
5944|    char* const oend = (ostart != NULL) ? ostart + output->size : ostart;
5945|    char* op = (ostart != NULL) ? ostart + output->pos : ostart;
5946|    U32 someMoreWork = 1;
5947|
5948|    /* check expectations */
5949|    DEBUGLOG(5, "ZSTD_compressStream_generic, flush=%i, srcSize = %zu", (int)flushMode, input->size - input->pos);
5950|    assert(zcs != NULL);
5951|    if (zcs->appliedParams.inBufferMode == ZSTD_bm_stable) {
5952|        assert(input->pos >= zcs->stableIn_notConsumed);
5953|        input->pos -= zcs->stableIn_notConsumed;
5954|        ip -= zcs->stableIn_notConsumed;
5955|        zcs->stableIn_notConsumed = 0;
5956|    }
5957|    if (zcs->appliedParams.inBufferMode == ZSTD_bm_buffered) {
5958|        assert(zcs->inBuff != NULL);
5959|        assert(zcs->inBuffSize > 0);
5960|    }
5961|    if (zcs->appliedParams.outBufferMode == ZSTD_bm_buffered) {
5962|        assert(zcs->outBuff !=  NULL);
5963|        assert(zcs->outBuffSize > 0);
5964|    }
5965|    if (input->src == NULL) assert(input->size == 0);
5966|    assert(input->pos <= input->size);
5967|    if (output->dst == NULL) assert(output->size == 0);
5968|    assert(output->pos <= output->size);
5969|    assert((U32)flushMode <= (U32)ZSTD_e_end);
5970|
5971|    while (someMoreWork) {
5972|        switch(zcs->streamStage)
5973|        {
5974|        case zcss_init:
5975|            RETURN_ERROR(init_missing, "call ZSTD_initCStream() first!");
5976|
5977|        case zcss_load:
5978|            if ( (flushMode == ZSTD_e_end)
5979|              && ( (size_t)(oend-op) >= ZSTD_compressBound(iend-ip)     /* Enough output space */
5980|                || zcs->appliedParams.outBufferMode == ZSTD_bm_stable)  /* OR we are allowed to return dstSizeTooSmall */
5981|              && (zcs->inBuffPos == 0) ) {
5982|                /* shortcut to compression pass directly into output buffer */
5983|                size_t const cSize = ZSTD_compressEnd_public(zcs,
5984|                                                op, oend-op, ip, iend-ip);
5985|                DEBUGLOG(4, "ZSTD_compressEnd : cSize=%u", (unsigned)cSize);
5986|                FORWARD_IF_ERROR(cSize, "ZSTD_compressEnd failed");
5987|                ip = iend;
5988|                op += cSize;
5989|                zcs->frameEnded = 1;
5990|                ZSTD_CCtx_reset(zcs, ZSTD_reset_session_only);
5991|                someMoreWork = 0; break;
5992|            }
5993|            /* complete loading into inBuffer in buffered mode */
5994|            if (zcs->appliedParams.inBufferMode == ZSTD_bm_buffered) {
5995|                size_t const toLoad = zcs->inBuffTarget - zcs->inBuffPos;
5996|                size_t const loaded = ZSTD_limitCopy(
5997|                                        zcs->inBuff + zcs->inBuffPos, toLoad,
5998|                                        ip, iend-ip);
5999|                zcs->inBuffPos += loaded;
6000|                if (ip) ip += loaded;
6001|                if ( (flushMode == ZSTD_e_continue)
6002|                  && (zcs->inBuffPos < zcs->inBuffTarget) ) {
6003|                    /* not enough input to fill full block : stop here */
6004|                    someMoreWork = 0; break;
6005|                }
6006|                if ( (flushMode == ZSTD_e_flush)
6007|                  && (zcs->inBuffPos == zcs->inToCompress) ) {
6008|                    /* empty */
6009|                    someMoreWork = 0; break;
6010|                }
6011|            } else {
6012|                assert(zcs->appliedParams.inBufferMode == ZSTD_bm_stable);
6013|                if ( (flushMode == ZSTD_e_continue)
6014|                  && ( (size_t)(iend - ip) < zcs->blockSize) ) {
6015|                    /* can't compress a full block : stop here */
6016|                    zcs->stableIn_notConsumed = (size_t)(iend - ip);
6017|                    ip = iend;  /* pretend to have consumed input */
6018|                    someMoreWork = 0; break;
6019|                }
6020|                if ( (flushMode == ZSTD_e_flush)
6021|                  && (ip == iend) ) {
6022|                    /* empty */
6023|                    someMoreWork = 0; break;
6024|                }
6025|            }
6026|            /* compress current block (note : this stage cannot be stopped in the middle) */
6027|            DEBUGLOG(5, "stream compression stage (flushMode==%u)", flushMode);
6028|            {   int const inputBuffered = (zcs->appliedParams.inBufferMode == ZSTD_bm_buffered);
6029|                void* cDst;
6030|                size_t cSize;
6031|                size_t oSize = oend-op;
6032|                size_t const iSize = inputBuffered ? zcs->inBuffPos - zcs->inToCompress
6033|                                                   : MIN((size_t)(iend - ip), zcs->blockSize);
6034|                if (oSize >= ZSTD_compressBound(iSize) || zcs->appliedParams.outBufferMode == ZSTD_bm_stable)
6035|                    cDst = op;   /* compress into output buffer, to skip flush stage */
6036|                else
6037|                    cDst = zcs->outBuff, oSize = zcs->outBuffSize;
6038|                if (inputBuffered) {
6039|                    unsigned const lastBlock = (flushMode == ZSTD_e_end) && (ip==iend);
6040|                    cSize = lastBlock ?
6041|                            ZSTD_compressEnd_public(zcs, cDst, oSize,
6042|                                        zcs->inBuff + zcs->inToCompress, iSize) :
6043|                            ZSTD_compressContinue_public(zcs, cDst, oSize,
6044|                                        zcs->inBuff + zcs->inToCompress, iSize);
6045|                    FORWARD_IF_ERROR(cSize, "%s", lastBlock ? "ZSTD_compressEnd failed" : "ZSTD_compressContinue failed");
6046|                    zcs->frameEnded = lastBlock;
6047|                    /* prepare next block */
6048|                    zcs->inBuffTarget = zcs->inBuffPos + zcs->blockSize;
6049|                    if (zcs->inBuffTarget > zcs->inBuffSize)
6050|                        zcs->inBuffPos = 0, zcs->inBuffTarget = zcs->blockSize;
6051|                    DEBUGLOG(5, "inBuffTarget:%u / inBuffSize:%u",
6052|                            (unsigned)zcs->inBuffTarget, (unsigned)zcs->inBuffSize);
6053|                    if (!lastBlock)
6054|                        assert(zcs->inBuffTarget <= zcs->inBuffSize);
6055|                    zcs->inToCompress = zcs->inBuffPos;
6056|                } else { /* !inputBuffered, hence ZSTD_bm_stable */
6057|                    unsigned const lastBlock = (flushMode == ZSTD_e_end) && (ip + iSize == iend);
6058|                    cSize = lastBlock ?
6059|                            ZSTD_compressEnd_public(zcs, cDst, oSize, ip, iSize) :
6060|                            ZSTD_compressContinue_public(zcs, cDst, oSize, ip, iSize);
