6196|                : (cctx->cdict ? cctx->cdict->dictContentSize : 0);
6197|        ZSTD_cParamMode_e const mode = ZSTD_getCParamMode(cctx->cdict, &params, cctx->pledgedSrcSizePlusOne - 1);
6198|        params.cParams = ZSTD_getCParamsFromCCtxParams(
6199|                &params, cctx->pledgedSrcSizePlusOne-1,
6200|                dictSize, mode);
