6271|/* @return provides a minimum amount of data remaining to be flushed from internal buffers
6272| */
6273|size_t ZSTD_compressStream2( ZSTD_CCtx* cctx,
6274|                             ZSTD_outBuffer* output,
6275|                             ZSTD_inBuffer* input,
6276|                             ZSTD_EndDirective endOp)
6277|{
6278|    DEBUGLOG(5, "ZSTD_compressStream2, endOp=%u ", (unsigned)endOp);
6279|    /* check conditions */
6280|    RETURN_ERROR_IF(output->pos > output->size, dstSize_tooSmall, "invalid output buffer");
6281|    RETURN_ERROR_IF(input->pos  > input->size, srcSize_wrong, "invalid input buffer");
6282|    RETURN_ERROR_IF((U32)endOp > (U32)ZSTD_e_end, parameter_outOfBound, "invalid endDirective");
6283|    assert(cctx != NULL);
6284|
6285|    /* transparent initialization stage */
6286|    if (cctx->streamStage == zcss_init) {
6287|        size_t const inputSize = input->size - input->pos;  /* no obligation to start from pos==0 */
6288|        size_t const totalInputSize = inputSize + cctx->stableIn_notConsumed;
6289|        if ( (cctx->requestedParams.inBufferMode == ZSTD_bm_stable) /* input is presumed stable, across invocations */
6290|          && (endOp == ZSTD_e_continue)                             /* no flush requested, more input to come */
6291|          && (totalInputSize < ZSTD_BLOCKSIZE_MAX) ) {              /* not even reached one block yet */
6292|            if (cctx->stableIn_notConsumed) {  /* not the first time */
6293|                /* check stable source guarantees */
6294|                RETURN_ERROR_IF(input->src != cctx->expectedInBuffer.src, stabilityCondition_notRespected, "stableInBuffer condition not respected: wrong src pointer");
6295|                RETURN_ERROR_IF(input->pos != cctx->expectedInBuffer.size, stabilityCondition_notRespected, "stableInBuffer condition not respected: externally modified pos");
6296|            }
6297|            /* pretend input was consumed, to give a sense forward progress */
6298|            input->pos = input->size;
6299|            /* save stable inBuffer, for later control, and flush/end */
6300|            cctx->expectedInBuffer = *input;
6301|            /* but actually input wasn't consumed, so keep track of position from where compression shall resume */
6302|            cctx->stableIn_notConsumed += inputSize;
6303|            /* don't initialize yet, wait for the first block of flush() order, for better parameters adaptation */
6304|            return ZSTD_FRAMEHEADERSIZE_MIN(cctx->requestedParams.format);  /* at least some header to produce */
6305|        }
6306|        FORWARD_IF_ERROR(ZSTD_CCtx_init_compressStream2(cctx, endOp, totalInputSize), "compressStream2 initialization failed");
6307|        ZSTD_setBufferExpectations(cctx, output, input);   /* Set initial buffer expectations now that we've initialized */
6308|    }
6309|    /* end of transparent initialization stage */
6310|
6311|    FORWARD_IF_ERROR(ZSTD_checkBufferStability(cctx, output, input, endOp), "invalid buffers");
6312|    /* compression stage */
6313|#ifdef ZSTD_MULTITHREAD
6314|    if (cctx->appliedParams.nbWorkers > 0) {
6315|        size_t flushMin;
6316|        if (cctx->cParamsChanged) {
6317|            ZSTDMT_updateCParams_whileCompressing(cctx->mtctx, &cctx->requestedParams);
6318|            cctx->cParamsChanged = 0;
6319|        }
6320|        if (cctx->stableIn_notConsumed) {
6321|            assert(cctx->appliedParams.inBufferMode == ZSTD_bm_stable);
6322|            /* some early data was skipped - make it available for consumption */
6323|            assert(input->pos >= cctx->stableIn_notConsumed);
6324|            input->pos -= cctx->stableIn_notConsumed;
6325|            cctx->stableIn_notConsumed = 0;
6326|        }
6327|        for (;;) {
6328|            size_t const ipos = input->pos;
6329|            size_t const opos = output->pos;
6330|            flushMin = ZSTDMT_compressStream_generic(cctx->mtctx, output, input, endOp);
6331|            cctx->consumedSrcSize += (U64)(input->pos - ipos);
6332|            cctx->producedCSize += (U64)(output->pos - opos);
6333|            if ( ZSTD_isError(flushMin)
6334|              || (endOp == ZSTD_e_end && flushMin == 0) ) { /* compression completed */
6335|                if (flushMin == 0)
6336|                    ZSTD_CCtx_trace(cctx, 0);
6337|                ZSTD_CCtx_reset(cctx, ZSTD_reset_session_only);
6338|            }
6339|            FORWARD_IF_ERROR(flushMin, "ZSTDMT_compressStream_generic failed");
6340|
6341|            if (endOp == ZSTD_e_continue) {
6342|                /* We only require some progress with ZSTD_e_continue, not maximal progress.
6343|                 * We're done if we've consumed or produced any bytes, or either buffer is
6344|                 * full.
6345|                 */
6346|                if (input->pos != ipos || output->pos != opos || input->pos == input->size || output->pos == output->size)
6347|                    break;
6348|            } else {
6349|                assert(endOp == ZSTD_e_flush || endOp == ZSTD_e_end);
6350|                /* We require maximal progress. We're done when the flush is complete or the
6351|                 * output buffer is full.
6352|                 */
6353|                if (flushMin == 0 || output->pos == output->size)
6354|                    break;
6355|            }
6356|        }
6357|        DEBUGLOG(5, "completed ZSTD_compressStream2 delegating to ZSTDMT_compressStream_generic");
6358|        /* Either we don't require maximum forward progress, we've finished the
6359|         * flush, or we are out of output space.
6360|         */
6361|        assert(endOp == ZSTD_e_continue || flushMin == 0 || output->pos == output->size);
6362|        ZSTD_setBufferExpectations(cctx, output, input);
6363|        return flushMin;
6364|    }
6365|#endif /* ZSTD_MULTITHREAD */
6366|    FORWARD_IF_ERROR( ZSTD_compressStream_generic(cctx, output, input, endOp) , "");
6367|    DEBUGLOG(5, "completed ZSTD_compressStream2");
6368|    ZSTD_setBufferExpectations(cctx, output, input);
6369|    return cctx->outBuffContentSize - cctx->outBuffFlushedSize; /* remaining to flush */
6370|}
