6425|/* ZSTD_validateSequence() :
6426| * @offCode : is presumed to follow format required by ZSTD_storeSeq()
6427| * @returns a ZSTD error code if sequence is not valid
6428| */
6429|static size_t
6430|ZSTD_validateSequence(U32 offCode, U32 matchLength, U32 minMatch,
6431|                      size_t posInSrc, U32 windowLog, size_t dictSize, int useSequenceProducer)
6432|{
6433|    U32 const windowSize = 1u << windowLog;
6434|    /* posInSrc represents the amount of data the decoder would decode up to this point.
6435|     * As long as the amount of data decoded is less than or equal to window size, offsets may be
6436|     * larger than the total length of output decoded in order to reference the dict, even larger than
6437|     * window size. After output surpasses windowSize, we're limited to windowSize offsets again.
6438|     */
6439|    size_t const offsetBound = posInSrc > windowSize ? (size_t)windowSize : posInSrc + (size_t)dictSize;
6440|    size_t const matchLenLowerBound = (minMatch == 3 || useSequenceProducer) ? 3 : 4;
6441|    RETURN_ERROR_IF(offCode > OFFSET_TO_OFFBASE(offsetBound), externalSequences_invalid, "Offset too large!");
6442|    /* Validate maxNbSeq is large enough for the given matchLength and minMatch */
6443|    RETURN_ERROR_IF(matchLength < matchLenLowerBound, externalSequences_invalid, "Matchlength too small for the minMatch");
6444|    return 0;
