6447|/* Returns an offset code, given a sequence's raw offset, the ongoing repcode array, and whether litLength == 0 */
6448|static U32 ZSTD_finalizeOffBase(U32 rawOffset, const U32 rep[ZSTD_REP_NUM], U32 ll0)
6449|{
