6452|    if (!ll0 && rawOffset == rep[0]) {
6453|        offBase = REPCODE1_TO_OFFBASE;
6454|    } else if (rawOffset == rep[1]) {
6455|        offBase = REPCODE_TO_OFFBASE(2 - ll0);
6456|    } else if (rawOffset == rep[2]) {
6457|        offBase = REPCODE_TO_OFFBASE(3 - ll0);
6458|    } else if (ll0 && rawOffset == rep[0] - 1) {
6459|        offBase = REPCODE3_TO_OFFBASE;
