6587|            if (startPosInSequence >= litLength) {
6588|                startPosInSequence -= litLength;
6589|                litLength = 0;
6590|                matchLength -= startPosInSequence;
6591|            } else {
6592|                litLength -= startPosInSequence;
6593|            }
6594|            /* Move to the next sequence */
6595|            endPosInSequence -= currSeq.litLength + currSeq.matchLength;
6596|            startPosInSequence = 0;
6597|        } else {
