6689|/* Discover the size of next block by searching for the delimiter.
6690| * Note that a block delimiter **must** exist in this mode,
6691| * otherwise it's an input error.
6692| * The block size retrieved will be later compared to ensure it remains within bounds */
6693|static size_t
6694|blockSize_explicitDelimiter(const ZSTD_Sequence* inSeqs, size_t inSeqsSize, ZSTD_sequencePosition seqPos)
6695|{
6696|    int end = 0;
6697|    size_t blockSize = 0;
6698|    size_t spos = seqPos.idx;
6699|    DEBUGLOG(6, "blockSize_explicitDelimiter : seq %zu / %zu", spos, inSeqsSize);
6700|    assert(spos <= inSeqsSize);
6701|    while (spos < inSeqsSize) {
6702|        end = (inSeqs[spos].offset == 0);
6703|        blockSize += inSeqs[spos].litLength + inSeqs[spos].matchLength;
6704|        if (end) {
6705|            if (inSeqs[spos].matchLength != 0)
6706|                RETURN_ERROR(externalSequences_invalid, "delimiter format error : both matchlength and offset must be == 0");
6707|            break;
6708|        }
6709|        spos++;
6710|    }
6711|    if (!end)
6712|        RETURN_ERROR(externalSequences_invalid, "Reached end of sequences without finding a block delimiter");
6713|    return blockSize;
