6723|static size_t determine_blockSize(ZSTD_sequenceFormat_e mode,
6724|                           size_t blockSize, size_t remaining,
6725|                     const ZSTD_Sequence* inSeqs, size_t inSeqsSize, ZSTD_sequencePosition seqPos)
6726|{
6727|    DEBUGLOG(6, "determine_blockSize : remainingSize = %zu", remaining);
6728|    if (mode == ZSTD_sf_noBlockDelimiters)
6729|        return blockSize_noDelimiter(blockSize, remaining);
6730|    {   size_t const explicitBlockSize = blockSize_explicitDelimiter(inSeqs, inSeqsSize, seqPos);
6731|        FORWARD_IF_ERROR(explicitBlockSize, "Error while determining block size with explicit delimiters");
6732|        if (explicitBlockSize > blockSize)
