6740|/* Compress, block-by-block, all of the sequences given.
6741| *
6742| * Returns the cumulative size of all compressed blocks (including their headers),
6743| * otherwise a ZSTD error.
6744| */
6745|static size_t
6746|ZSTD_compressSequences_internal(ZSTD_CCtx* cctx,
6747|                                void* dst, size_t dstCapacity,
6748|                          const ZSTD_Sequence* inSeqs, size_t inSeqsSize,
6749|                          const void* src, size_t srcSize)
6750|{
6751|    size_t cSize = 0;
6752|    size_t remaining = srcSize;
6753|    ZSTD_sequencePosition seqPos = {0, 0, 0};
6754|
6755|    BYTE const* ip = (BYTE const*)src;
6756|    BYTE* op = (BYTE*)dst;
6757|    ZSTD_sequenceCopier const sequenceCopier = ZSTD_selectSequenceCopier(cctx->appliedParams.blockDelimiters);
6758|
6759|    DEBUGLOG(4, "ZSTD_compressSequences_internal srcSize: %zu, inSeqsSize: %zu", srcSize, inSeqsSize);
6760|    /* Special case: empty frame */
6761|    if (remaining == 0) {
6762|        U32 const cBlockHeader24 = 1 /* last block */ + (((U32)bt_raw)<<1);
6763|        RETURN_ERROR_IF(dstCapacity<4, dstSize_tooSmall, "No room for empty frame block header");
6764|        MEM_writeLE32(op, cBlockHeader24);
6765|        op += ZSTD_blockHeaderSize;
6766|        dstCapacity -= ZSTD_blockHeaderSize;
6767|        cSize += ZSTD_blockHeaderSize;
6768|    }
6769|
6770|    while (remaining) {
6771|        size_t compressedSeqsSize;
6772|        size_t cBlockSize;
6773|        size_t additionalByteAdjustment;
6774|        size_t blockSize = determine_blockSize(cctx->appliedParams.blockDelimiters,
6775|                                        cctx->blockSize, remaining,
6776|                                        inSeqs, inSeqsSize, seqPos);
6777|        U32 const lastBlock = (blockSize == remaining);
6778|        FORWARD_IF_ERROR(blockSize, "Error while trying to determine block size");
6779|        assert(blockSize <= remaining);
6780|        ZSTD_resetSeqStore(&cctx->seqStore);
6781|        DEBUGLOG(5, "Working on new block. Blocksize: %zu (total:%zu)", blockSize, (ip - (const BYTE*)src) + blockSize);
6782|
6783|        additionalByteAdjustment = sequenceCopier(cctx, &seqPos, inSeqs, inSeqsSize, ip, blockSize, cctx->appliedParams.searchForExternalRepcodes);
6784|        FORWARD_IF_ERROR(additionalByteAdjustment, "Bad sequence copy");
6785|        blockSize -= additionalByteAdjustment;
6786|
6787|        /* If blocks are too small, emit as a nocompress block */
6788|        /* TODO: See 3090. We reduced MIN_CBLOCK_SIZE from 3 to 2 so to compensate we are adding
6789|         * additional 1. We need to revisit and change this logic to be more consistent */
6790|        if (blockSize < MIN_CBLOCK_SIZE+ZSTD_blockHeaderSize+1+1) {
6791|            cBlockSize = ZSTD_noCompressBlock(op, dstCapacity, ip, blockSize, lastBlock);
6792|            FORWARD_IF_ERROR(cBlockSize, "Nocompress block failed");
6793|            DEBUGLOG(5, "Block too small, writing out nocompress block: cSize: %zu", cBlockSize);
6794|            cSize += cBlockSize;
6795|            ip += blockSize;
6796|            op += cBlockSize;
6797|            remaining -= blockSize;
6798|            dstCapacity -= cBlockSize;
6799|            continue;
6800|        }
6801|
6802|        RETURN_ERROR_IF(dstCapacity < ZSTD_blockHeaderSize, dstSize_tooSmall, "not enough dstCapacity to write a new compressed block");
6803|        compressedSeqsSize = ZSTD_entropyCompressSeqStore(&cctx->seqStore,
6804|                                &cctx->blockState.prevCBlock->entropy, &cctx->blockState.nextCBlock->entropy,
6805|                                &cctx->appliedParams,
6806|                                op + ZSTD_blockHeaderSize /* Leave space for block header */, dstCapacity - ZSTD_blockHeaderSize,
6807|                                blockSize,
6808|                                cctx->entropyWorkspace, ENTROPY_WORKSPACE_SIZE /* statically allocated in resetCCtx */,
6809|                                cctx->bmi2);
