6843|            DEBUGLOG(5, "Writing out compressed block, size: %zu", cBlockSize);
6844|        }
6845|
6846|        cSize += cBlockSize;
6847|
6848|        if (lastBlock) {
6849|            break;
6850|        } else {
6851|            ip += blockSize;
6852|            op += cBlockSize;
6853|            remaining -= blockSize;
6854|            dstCapacity -= cBlockSize;
6855|            cctx->isFirstBlock = 0;
6856|        }
6857|        DEBUGLOG(5, "cSize running total: %zu (remaining dstCapacity=%zu)", cSize, dstCapacity);
6858|    }
6859|
6860|    DEBUGLOG(4, "cSize final total: %zu", cSize);
6861|    return cSize;
