6864|size_t ZSTD_compressSequences(ZSTD_CCtx* cctx,
6865|                              void* dst, size_t dstCapacity,
6866|                              const ZSTD_Sequence* inSeqs, size_t inSeqsSize,
6867|                              const void* src, size_t srcSize)
6868|{
6869|    BYTE* op = (BYTE*)dst;
6870|    size_t cSize = 0;
6871|    size_t compressedBlocksSize = 0;
6872|    size_t frameHeaderSize = 0;
6873|
6874|    /* Transparent initialization stage, same as compressStream2() */
6875|    DEBUGLOG(4, "ZSTD_compressSequences (dstCapacity=%zu)", dstCapacity);
6876|    assert(cctx != NULL);
6877|    FORWARD_IF_ERROR(ZSTD_CCtx_init_compressStream2(cctx, ZSTD_e_end, srcSize), "CCtx initialization failed");
6878|    /* Begin writing output, starting with frame header */
6879|    frameHeaderSize = ZSTD_writeFrameHeader(op, dstCapacity, &cctx->appliedParams, srcSize, cctx->dictID);
6880|    op += frameHeaderSize;
6881|    dstCapacity -= frameHeaderSize;
6882|    cSize += frameHeaderSize;
6883|    if (cctx->appliedParams.fParams.checksumFlag && srcSize) {
6884|        XXH64_update(&cctx->xxhState, src, srcSize);
6885|    }
6886|    /* cSize includes block header size and compressed sequences size */
6887|    compressedBlocksSize = ZSTD_compressSequences_internal(cctx,
6888|                                                           op, dstCapacity,
6889|                                                           inSeqs, inSeqsSize,
6890|                                                           src, srcSize);
6891|    FORWARD_IF_ERROR(compressedBlocksSize, "Compressing blocks failed!");
6892|    cSize += compressedBlocksSize;
6893|    dstCapacity -= compressedBlocksSize;
6894|
6895|    if (cctx->appliedParams.fParams.checksumFlag) {
6896|        U32 const checksum = (U32) XXH64_digest(&cctx->xxhState);
6897|        RETURN_ERROR_IF(dstCapacity<4, dstSize_tooSmall, "no room for checksum");
6898|        DEBUGLOG(4, "Write checksum : %08X", (unsigned)checksum);
6899|        MEM_writeLE32((char*)dst + cSize, checksum);
6900|        cSize += 4;
6901|    }
6902|
6903|    DEBUGLOG(4, "Final compressed size: %zu", cSize);
6904|    return cSize;
