6926|size_t ZSTD_endStream(ZSTD_CStream* zcs, ZSTD_outBuffer* output)
6927|{
6928|    ZSTD_inBuffer input = inBuffer_forEndFlush(zcs);
6929|    size_t const remainingToFlush = ZSTD_compressStream2(zcs, output, &input, ZSTD_e_end);
6930|    FORWARD_IF_ERROR(remainingToFlush , "ZSTD_compressStream2(,,ZSTD_e_end) failed");
6931|    if (zcs->appliedParams.nbWorkers > 0) return remainingToFlush;   /* minimal estimation */
6932|    /* single thread mode : attempt to calculate remaining to flush more precisely */
6933|    {   size_t const lastBlockSize = zcs->frameEnded ? 0 : ZSTD_BLOCKHEADERSIZE;
6934|        size_t const checksumSize = (size_t)(zcs->frameEnded ? 0 : zcs->appliedParams.fParams.checksumFlag * 4);
6935|        size_t const toFlush = remainingToFlush + lastBlockSize + checksumSize;
6936|        DEBUGLOG(4, "ZSTD_endStream : remaining to flush : %u", (unsigned)toFlush);
