7026|/*! ZSTD_getCParams_internal() :
7027| * @return ZSTD_compressionParameters structure for a selected compression level, srcSize and dictSize.
7028| *  Note: srcSizeHint 0 means 0, use ZSTD_CONTENTSIZE_UNKNOWN for unknown.
7029| *        Use dictSize == 0 for unknown or unused.
7030| *  Note: `mode` controls how we treat the `dictSize`. See docs for `ZSTD_cParamMode_e`. */
7031|static ZSTD_compressionParameters ZSTD_getCParams_internal(int compressionLevel, unsigned long long srcSizeHint, size_t dictSize, ZSTD_cParamMode_e mode)
7032|{
7033|    U64 const rSize = ZSTD_getCParamRowSize(srcSizeHint, dictSize, mode);
7034|    U32 const tableID = (rSize <= 256 KB) + (rSize <= 128 KB) + (rSize <= 16 KB);
7035|    int row;
7036|    DEBUGLOG(5, "ZSTD_getCParams_internal (cLevel=%i)", compressionLevel);
7037|
7038|    /* row */
7039|    if (compressionLevel == 0) row = ZSTD_CLEVEL_DEFAULT;   /* 0 == default */
7040|    else if (compressionLevel < 0) row = 0;   /* entry 0 is baseline for fast mode */
7041|    else if (compressionLevel > ZSTD_MAX_CLEVEL) row = ZSTD_MAX_CLEVEL;
7042|    else row = compressionLevel;
7043|
7044|    {   ZSTD_compressionParameters cp = ZSTD_defaultCParameters[tableID][row];
7045|        DEBUGLOG(5, "ZSTD_getCParams_internal selected tableID: %u row: %u strat: %u", tableID, row, (U32)cp.strategy);
