3363|static void ZSTD_copyBlockSequences(ZSTD_CCtx* zc)
3364|{
3365|    const seqStore_t* seqStore = ZSTD_getSeqStore(zc);
3366|    const seqDef* seqStoreSeqs = seqStore->sequencesStart;
3367|    size_t seqStoreSeqSize = seqStore->sequences - seqStoreSeqs;
3368|    size_t seqStoreLiteralsSize = (size_t)(seqStore->lit - seqStore->litStart);
3369|    size_t literalsRead = 0;
3370|    size_t lastLLSize;
3371|
3372|    ZSTD_Sequence* outSeqs = &zc->seqCollector.seqStart[zc->seqCollector.seqIndex];
3373|    size_t i;
3374|    repcodes_t updatedRepcodes;
3375|
3376|    assert(zc->seqCollector.seqIndex + 1 < zc->seqCollector.maxSequences);
3377|    /* Ensure we have enough space for last literals "sequence" */
3378|    assert(zc->seqCollector.maxSequences >= seqStoreSeqSize + 1);
3379|    ZSTD_memcpy(updatedRepcodes.rep, zc->blockState.prevCBlock->rep, sizeof(repcodes_t));
3380|    for (i = 0; i < seqStoreSeqSize; ++i) {
3381|        U32 rawOffset = seqStoreSeqs[i].offBase - ZSTD_REP_NUM;
3382|        outSeqs[i].litLength = seqStoreSeqs[i].litLength;
3383|        outSeqs[i].matchLength = seqStoreSeqs[i].mlBase + MINMATCH;
3384|        outSeqs[i].rep = 0;
3385|
3386|        if (i == seqStore->longLengthPos) {
3387|            if (seqStore->longLengthType == ZSTD_llt_literalLength) {
3388|                outSeqs[i].litLength += 0x10000;
3389|            } else if (seqStore->longLengthType == ZSTD_llt_matchLength) {
3390|                outSeqs[i].matchLength += 0x10000;
3391|            }
3392|        }
3393|
3394|        if (seqStoreSeqs[i].offBase <= ZSTD_REP_NUM) {
3395|            /* Derive the correct offset corresponding to a repcode */
3396|            outSeqs[i].rep = seqStoreSeqs[i].offBase;
3397|            if (outSeqs[i].litLength != 0) {
3398|                rawOffset = updatedRepcodes.rep[outSeqs[i].rep - 1];
3399|            } else {
3400|                if (outSeqs[i].rep == 3) {
3401|                    rawOffset = updatedRepcodes.rep[0] - 1;
3402|                } else {
3403|                    rawOffset = updatedRepcodes.rep[outSeqs[i].rep];
3404|                }
3405|            }
3406|        }
3407|        outSeqs[i].offset = rawOffset;
3408|        /* seqStoreSeqs[i].offset == offCode+1, and ZSTD_updateRep() expects offCode
3409|           so we provide seqStoreSeqs[i].offset - 1 */
3410|        ZSTD_updateRep(updatedRepcodes.rep,
3411|                       seqStoreSeqs[i].offBase,
3412|                       seqStoreSeqs[i].litLength == 0);
3413|        literalsRead += outSeqs[i].litLength;
3414|    }
3415|    /* Insert last literals (if any exist) in the block as a sequence with ml == off == 0.
3416|     * If there are no last literals, then we'll emit (of: 0, ml: 0, ll: 0), which is a marker
3417|     * for the block boundary, according to the API.
3418|     */
3419|    assert(seqStoreLiteralsSize >= literalsRead);
3420|    lastLLSize = seqStoreLiteralsSize - literalsRead;
3421|    outSeqs[i].litLength = (U32)lastLLSize;
3422|    outSeqs[i].matchLength = outSeqs[i].offset = outSeqs[i].rep = 0;
3423|    seqStoreSeqSize++;
3424|    zc->seqCollector.seqIndex += seqStoreSeqSize;
3425|}

